using UnityEngine;
using System.Collections.Generic;

//모든 스크립트의 디버그 로그 를 관여하는 디버그 로그 매니져및 로그매니져 
public class LogManager : MonoBehaviour
{
    public enum LogCategory
    {
        Default,
        ServerManager,
        PlayerManager,
        UIManager,
        SoundManager,
        SettingsManager,
        ItemManager,
        PostManager,
        CharacterManager,
        ObjectPoolSpawner,
        PlayStateManager,
        VamserLikeGameManager,
        NormalMob,
        PlayerBase,
        SceneLoader,
        InventoryManager
    }
    public static LogManager Instance { get; private set; }
    [SerializeField] private bool enableDebugLog = true;
    [SerializeField] private bool enableErrorLog = true;
    [SerializeField] private bool enableWarningLog = true;
    private void Awake()
    {
        if (Instance != null && Instance != this)
        {
            Destroy(gameObject);
            return;
        }
        Instance = this;
        DontDestroyOnLoad(gameObject);
    }

    // 각 매니저별 로그 활성화 설정
    [System.Serializable]
    public class LogCategorySetting {
        public string categoryName;
        public bool enableLog = true;
    }
    [SerializeField]
    private List<LogCategorySetting> logCategorySettings = new List<LogCategorySetting> {
        new LogCategorySetting { categoryName = "Default", enableLog = true },
        new LogCategorySetting { categoryName = "ServerManager", enableLog = true },
        new LogCategorySetting { categoryName = "PlayerManager", enableLog = true },
        new LogCategorySetting { categoryName = "UIManager", enableLog = true },
        new LogCategorySetting { categoryName = "SoundManager", enableLog = true },
        new LogCategorySetting { categoryName = "SettingsManager", enableLog = true },
        new LogCategorySetting { categoryName = "ItemManager", enableLog = true },
        new LogCategorySetting { categoryName = "PostManager", enableLog = true },
        new LogCategorySetting { categoryName = "CharacterManager", enableLog = true },
        new LogCategorySetting { categoryName = "ObjectPoolSpawner", enableLog = true },
        new LogCategorySetting { categoryName = "PlayStateManager", enableLog = true },
        new LogCategorySetting { categoryName = "VamserLikeGameManager", enableLog = true },
        new LogCategorySetting { categoryName = "NormalMob", enableLog = true },
        new LogCategorySetting { categoryName = "PlayerBase", enableLog = true },
        new LogCategorySetting { categoryName = "SceneLoader", enableLog = true },
        new LogCategorySetting { categoryName = "InventoryManager", enableLog = true },
        // 필요에 따라 추가
    };

    private bool IsCategoryEnabled(string category)
    {
        var setting = logCategorySettings.Find(x => x.categoryName == category);
        return setting != null ? setting.enableLog : true;
    }

    public static void Log(string message, string category = "Default", UnityEngine.Object context = null)
    {
#if UNITY_EDITOR || DEVELOPMENT_BUILD
        if (Instance == null || !Instance.enableDebugLog) return;
        if (!Instance.IsCategoryEnabled(category)) return;
        Debug.Log($"[{category}] {message}", context);
#endif
    }

    public static void LogWarning(string message, string category = "Default", UnityEngine.Object context = null)
    {
#if UNITY_EDITOR || DEVELOPMENT_BUILD
        if (Instance == null || !Instance.enableWarningLog) return;
        if (!Instance.IsCategoryEnabled(category)) return;
        Debug.LogWarning($"[{category}] {message}", context);
#endif
    }

    public static void LogError(string message, string category = "Default", UnityEngine.Object context = null)
    {
#if UNITY_EDITOR || DEVELOPMENT_BUILD
        if (Instance == null || !Instance.enableErrorLog) return;
        if (!Instance.IsCategoryEnabled(category)) return;
        Debug.LogError($"[{category}] {message}", context);
#endif
    }

    public static void LogException(System.Exception exception, string category = "Default", UnityEngine.Object context = null)
    {
#if UNITY_EDITOR || DEVELOPMENT_BUILD
        if (Instance == null || !Instance.enableErrorLog) return;
        if (!Instance.IsCategoryEnabled(category)) return;
        Debug.LogException(exception, context);
#endif
    }

    public void SetDebugLog(bool enabled) => enableDebugLog = enabled;
    public void SetErrorLog(bool enabled) => enableErrorLog = enabled;
    public void SetWarningLog(bool enabled) => enableWarningLog = enabled;

}

