using System.Collections.Generic;
using UnityEngine;

namespace DogGuns_Games.Lobby
{
    /// <summary>
    /// 캐릭터 선택 UI 관리 클래스
    /// </summary>
    public class CharacterSelectUIManager : MonoBehaviour
    {
        #region 필드 및 변수

        [Header("<color=green>캐릭터 선택창</color>")] 
        [SerializeField] private GameObject characterSelectPanel;

        [Header("<color=green>캐릭터 정보 확장창</color>")] 
        [SerializeField] private GameObject characterExpendViewPanel;

        [Header("<color=green>캐릭터 리스트</color>")] 
        [SerializeField] private GameObject characterListPanel;

        [Header("<color=green>캐릭터선택 관련</color>")] 
        [SerializeField] private CharactorSelectIndex characterSelectIndexPrefab;
        [SerializeField] private Transform characterSelectIndexParent;

        [Header("<color=green>캐릭터스킨 관련</color>")] 
        [SerializeField] private CharactorSkinIndex characterSkinIndexPrefab;
        [SerializeField] private Transform characterSkinIndexParent;

        // 캐릭터 및 스킨 데이터 캐싱
        private List<CharacterData> _characterDataList = new List<CharacterData>();
        private List<CharacterSkinData> _skinDataList = new List<CharacterSkinData>();

        // 현재 선택된 캐릭터/스킨 인덱스
        private int _currentCharacterIndex = 0;
        private int _currentSkinIndex = 0;

        // 생성된 UI 요소 참조 저장
        private List<CharactorSelectIndex> _characterIndexItems = new List<CharactorSelectIndex>();
        private List<CharactorSkinIndex> _skinIndexItems = new List<CharactorSkinIndex>();

        #endregion

        #region Unity 라이프사이클

        private void Awake()
        {
          //  InitializePanels();
        }

        private void Start()
        {
            LoadCharacterData();
            InitializeCharacterUI();
        }

        #endregion

        #region 초기화 메서드

        /// <summary>
        /// 패널 초기 상태 설정
        /// </summary>
        private void InitializePanels()
        {
            SetGameObjectActive(characterSelectPanel, false);
            SetGameObjectActive(characterExpendViewPanel, false);
            SetGameObjectActive(characterListPanel, false);
        }

        /// <summary>
        /// 캐릭터 데이터 로드
        /// </summary>
        private void LoadCharacterData()
        {
            // TODO: 캐릭터 및 스킨 데이터 로드 구현
            // 예: ScriptableObject, PlayerPrefs, 서버 등에서 불러오기
            Debug.Log("캐릭터 데이터 로드");

            // 이전에 선택된 캐릭터/스킨 인덱스 복원
            _currentCharacterIndex = PlayerDataManagerDontdesytoy.Instance?.SelectCharacterIndex ?? 0;
            _currentSkinIndex = PlayerPrefs.GetInt("SelectedSkinIndex", 0);
        }

        /// <summary>
        /// 캐릭터 선택 UI 초기화
        /// </summary>
        private void InitializeCharacterUI()
        {
            // 기존 UI 요소 정리
            ClearUIItems();

            // 캐릭터 선택 UI 생성
            CreateCharacterSelectItems();

            // 스킨 선택 UI 생성
            CreateSkinSelectItems(_currentCharacterIndex);

            Debug.Log($"캐릭터 UI 초기화 완료: 선택된 캐릭터 {_currentCharacterIndex}, 선택된 스킨 {_currentSkinIndex}");
        }

        /// <summary>
        /// UI 요소 정리
        /// </summary>
        private void ClearUIItems()
        {
            // 생성된 캐릭터 선택 UI 항목 제거
            foreach (var item in _characterIndexItems)
            {
                if (item != null) Destroy(item.gameObject);
            }
            _characterIndexItems.Clear();

            // 생성된 스킨 선택 UI 항목 제거
            foreach (var item in _skinIndexItems)
            {
                if (item != null) Destroy(item.gameObject);
            }
            _skinIndexItems.Clear();
        }

        /// <summary>
        /// 캐릭터 선택 항목 생성
        /// </summary>
        private void CreateCharacterSelectItems()
        {
            if (characterSelectIndexPrefab == null || characterSelectIndexParent == null)
            {
                Debug.LogError("캐릭터 선택 프리팹 또는 부모 트랜스폼이 설정되지 않았습니다.");
                return;
            }

            for (int i = 0; i < 5; i++)
            {
                var characterItem = Instantiate(characterSelectIndexPrefab, characterSelectIndexParent);
                if (characterItem.charactorName != null)
                {
                    characterItem.charactorName.text = $"캐릭터 {i}";
                }

                // 클릭 이벤트 설정
                int index = i; // 클로저를 위한 인덱스 변수
                var button = characterItem.GetComponent<UnityEngine.UI.Button>();
                if (button != null)
                {
                    button.onClick.AddListener(() => {
                        SelectCharacter(index);
                        OpenCharacterSkinViewPanel(); // 캐릭터 정보 확장창 열기
                    });
                }

                _characterIndexItems.Add(characterItem);
            }
        }

        /// <summary>
        /// 스킨 선택 항목 생성
        /// </summary>
        private void CreateSkinSelectItems(int characterIndex)
        {
            if (characterSkinIndexPrefab == null || characterSkinIndexParent == null)
            {
                Debug.LogError("스킨 선택 프리팹 또는 부모 트랜스폼이 설정되지 않았습니다.");
                return;
            }

            // TODO: 선택된 캐릭터의 스킨 데이터 기반으로 UI 생성
            // 예시: 테스트용 더미 데이터로 구현
            for (int i = 0; i < 3; i++)
            {
                var skinItem = Instantiate(characterSkinIndexPrefab, characterSkinIndexParent);
                if (skinItem.charactorName != null)
                {
                    skinItem.charactorName.text = $"스킨 {i}";
                }

                // 클릭 이벤트 설정
                int index = i; // 클로저를 위한 인덱스 변수
                var button = skinItem.GetComponent<UnityEngine.UI.Button>();
                if (button != null)
                {
                    button.onClick.AddListener(() => SelectSkin(index));
                }

                _skinIndexItems.Add(skinItem);
            }
        }

        #endregion

        #region 캐릭터 및 스킨 선택 메서드

        /// <summary>
        /// 캐릭터 선택 처리
        /// </summary>
        private void SelectCharacter(int characterIndex)
        {
            _currentCharacterIndex = characterIndex;

            // PlayerData에 선택한 캐릭터 인덱스 저장
            if (PlayerDataManagerDontdesytoy.Instance != null)
            {
                PlayerDataManagerDontdesytoy.Instance.SelectCharacterIndex = characterIndex;
            }

            // 스킨 UI 업데이트
            UpdateSkinUI(characterIndex);

            Debug.Log($"캐릭터 선택: {characterIndex}");
        }

        /// <summary>
        /// 스킨 선택 처리
        /// </summary>
        private void SelectSkin(int skinIndex)
        {
            _currentSkinIndex = skinIndex;

            // 선택한 스킨 인덱스 저장
            PlayerPrefs.SetInt("SelectedSkinIndex", skinIndex);
            PlayerPrefs.Save();

            Debug.Log($"스킨 선택: {skinIndex}");
        }

        /// <summary>
        /// 선택된 캐릭터에 따라 스킨 UI 업데이트
        /// </summary>
        private void UpdateSkinUI(int characterIndex)
        {
            // 기존 스킨 UI 항목 제거
            foreach (var item in _skinIndexItems)
            {
                if (item != null) Destroy(item.gameObject);
            }
            _skinIndexItems.Clear();

            // 선택된 캐릭터의 스킨 UI 다시 생성
            CreateSkinSelectItems(characterIndex);
        }

        #endregion

        #region UI 패널 제어 - 공개 메서드

        /// <summary>
        /// 캐릭터 선택 패널 열기
        /// </summary>
        public void OpenCharacterSelectPanel()
        {
            SetGameObjectActive(characterSelectPanel, true);
            LobbyUIManager.AddClosePopUpAction(CloseCharacterSelectPanel);

            // UI 초기화 - 최신 데이터로 리프레시
            InitializeCharacterUI();
        }

        /// <summary>
        /// 캐릭터 목록 패널 열기
        /// </summary>
        public void OpenCharacterListPanel()
        {
            SetGameObjectActive(characterListPanel, true);
            SetGameObjectActive(characterExpendViewPanel, false);
            LobbyUIManager.AddClosePopUpAction(CloseCharacterListPanel);
        }

        /// <summary>
        /// 캐릭터 스킬 보기 패널 열기
        /// </summary>
        public void OpenCharacterSkinViewPanel()
        {
            SetGameObjectActive(characterExpendViewPanel, true);
            SetGameObjectActive(characterListPanel, false);
            LobbyUIManager.AddClosePopUpAction(CloseCharacterSkinViewPanel);
        }

        /// <summary>
        /// 캐릭터 선택 패널 닫기
        /// </summary>
        public void CloseCharacterSelectPanel()
        {
            SetGameObjectActive(characterSelectPanel, false);
        }

        /// <summary>
        /// 캐릭터 목록 패널 닫기
        /// </summary>
        private void CloseCharacterListPanel()
        {
            SetGameObjectActive(characterListPanel, false);
        }

        /// <summary>
        /// 캐릭터 스킬 보기 패널 닫기
        /// </summary>
        private void CloseCharacterSkinViewPanel()
        {
            SetGameObjectActive(characterExpendViewPanel, false);
        }

        #endregion

        #region 유틸리티 메서드

        /// <summary>
        /// 게임 오브젝트 활성화/비활성화 처리
        /// </summary>
        /// <param name="obj">대상 게임 오브젝트</param>
        /// <param name="isActive">활성화 여부</param>
        private static void SetGameObjectActive(GameObject obj, bool isActive = false)
        {
            if (obj != null)
                obj.SetActive(isActive);
            else
                Debug.LogWarning("활성화하려는 게임 오브젝트가 null입니다.");
        }

        #endregion

        #region 데이터 클래스

        /// <summary>
        /// 캐릭터 데이터 구조체
        /// </summary>
        [System.Serializable]
        private struct CharacterData
        {
            public int index;         // 캐릭터 번호
            public string name;       // 캐릭터 이름
            public Sprite thumbnail;  // 캐릭터 썸네일
            public bool isUnlocked;   // 잠금 해제 여부
        }

        /// <summary>
        /// 캐릭터 스킨 데이터 구조체
        /// </summary>
        [System.Serializable]
        private struct CharacterSkinData
        {
            public int characterIndex; // 캐릭터 번호
            public int skinIndex;      // 스킨 번호
            public string name;        // 스킨 이름
            public Sprite thumbnail;   // 스킨 썸네일
            public bool isUnlocked;    // 잠금 해제 여부
        }

        #endregion
    }
}

using System.Collections.Generic;
using UnityEngine;

namespace DogGuns_Games.Lobby
{
    /// <summary>
    /// 캐릭터 선택 UI 관리 클래스
    /// </summary>
    public class CharacterSelectUIManager : MonoBehaviour
    {
        #region 필드 및 변수

        [Header("<color=green>캐릭터 선택창</color>")] 
        [SerializeField] private GameObject characterSelectPanel;

        [Header("<color=green>캐릭터 정보 확장창</color>")] 
        [SerializeField] private GameObject characterExpendViewPanel;

        [Header("<color=green>캐릭터 리스트</color>")] 
        [SerializeField] private GameObject characterListPanel;

        [Header("<color=green>캐릭터선택 관련</color>")] 
        [SerializeField] private CharactorSelectIndex characterSelectIndexPrefab;
        [SerializeField] private Transform characterSelectIndexParent;

        [Header("<color=green>캐릭터스킨 관련</color>")] 
        [SerializeField] private CharactorSkinIndex characterSkinIndexPrefab;
        [SerializeField] private Transform characterSkinIndexParent;

        // 캐릭터 및 스킨 데이터 캐싱
        private List<CharacterData> _characterDataList = new List<CharacterData>();
        private List<CharacterSkinData> _skinDataList = new List<CharacterSkinData>();

        // 현재 선택된 캐릭터/스킨 인덱스
        private int _currentCharacterIndex = 0;
        private int _currentSkinIndex = 0;

        // 생성된 UI 요소 참조 저장
        private List<CharactorSelectIndex> _characterIndexItems = new List<CharactorSelectIndex>();
        private List<CharactorSkinIndex> _skinIndexItems = new List<CharactorSkinIndex>();

        #endregion

        #region Unity 라이프사이클

        private void Awake()
        {
          //  InitializePanels();
        }

        private void Start()
        {
            LoadCharacterData();
            InitializeCharacterUI();
        }

        #endregion

        #region 초기화 메서드

        /// <summary>
        /// 패널 초기 상태 설정
        /// </summary>
        private void InitializePanels()
        {
            SetGameObjectActive(characterSelectPanel, false);
            SetGameObjectActive(characterExpendViewPanel, false);
            SetGameObjectActive(characterListPanel, false);
        }

        /// <summary>
        /// 캐릭터 데이터 로드
        /// </summary>
        private void LoadCharacterData()
        {
            // TODO: 캐릭터 및 스킨 데이터 로드 구현
            // 예: ScriptableObject, PlayerPrefs, 서버 등에서 불러오기
            LogManager.Log("캐릭터 데이터 로드");

            // 이전에 선택된 캐릭터/스킨 인덱스 복원
            _currentCharacterIndex = PlayerDataManagerDontdesytoy.Instance?.SelectCharacterIndex ?? 0;
            _currentSkinIndex = PlayerPrefs.GetInt("SelectedSkinIndex", 0);
        }

        /// <summary>
        /// 캐릭터 선택 UI 초기화
        /// </summary>
        private void InitializeCharacterUI()
        {
            // 기존 UI 요소 정리
            ClearUIItems();

            // 캐릭터 선택 UI 생성
            CreateCharacterSelectItems();

            // 스킨 선택 UI 생성
            CreateSkinSelectItems(_currentCharacterIndex);

            LogManager.Log($"캐릭터 UI 초기화 완료: 선택된 캐릭터 {_currentCharacterIndex}, 선택된 스킨 {_currentSkinIndex}");
        }

        /// <summary>
        /// UI 요소 정리
        /// </summary>
        private void ClearUIItems()
        {
            // 생성된 캐릭터 선택 UI 항목 제거
            foreach (var item in _characterIndexItems)
            {
                if (item != null) Destroy(item.gameObject);
            }
            _characterIndexItems.Clear();

            // 생성된 스킨 선택 UI 항목 제거
            foreach (var item in _skinIndexItems)
            {
                if (item != null) Destroy(item.gameObject);
            }
            _skinIndexItems.Clear();
        }

        /// <summary>
        /// 캐릭터 선택 항목 생성
        /// </summary>
        private void CreateCharacterSelectItems()
        {
            if (characterSelectIndexPrefab == null || characterSelectIndexParent == null)
            {
                LogManager.LogError("캐릭터 선택 프리팹 또는 부모 트랜스폼이 설정되지 않았습니다.");
                return;
            }

            for (int i = 0; i < 5; i++)
            {
                var characterItem = Instantiate(characterSelectIndexPrefab, characterSelectIndexParent);
                if (characterItem.charactorName != null)
                {
                    characterItem.charactorName.text = $"캐릭터 {i}";
                }

                // 클릭 이벤트 설정
                int index = i; // 클로저를 위한 인덱스 변수
                var button = characterItem.GetComponent<UnityEngine.UI.Button>();
                if (button != null)
                {
                    button.onClick.AddListener(() => {
                        SelectCharacter(index);
                        OpenCharacterSkinViewPanel(); // 캐릭터 정보 확장창 열기
                    });
                }

                _characterIndexItems.Add(characterItem);
            }
        }

        /// <summary>
        /// 스킨 선택 항목 생성
        /// </summary>
        private void CreateSkinSelectItems(int characterIndex)
        {
            if (characterSkinIndexPrefab == null || characterSkinIndexParent == null)
            {
                LogManager.LogError("스킨 선택 프리팹 또는 부모 트랜스폼이 설정되지 않았습니다.");
                return;
            }

            // TODO: 선택된 캐릭터의 스킨 데이터 기반으로 UI 생성
            // 예시: 테스트용 더미 데이터로 구현
            for (int i = 0; i < 3; i++)
            {
                var skinItem = Instantiate(characterSkinIndexPrefab, characterSkinIndexParent);
                if (skinItem.charactorName != null)
                {
                    skinItem.charactorName.text = $"스킨 {i}";
                }

                // 클릭 이벤트 설정
                int index = i; // 클로저를 위한 인덱스 변수
                var button = skinItem.GetComponent<UnityEngine.UI.Button>();
                if (button != null)
                {
                    button.onClick.AddListener(() => SelectSkin(index));
                }

                _skinIndexItems.Add(skinItem);
            }
        }

        #endregion

        #region 캐릭터 및 스킨 선택 메서드

        /// <summary>
        /// 캐릭터 선택 처리
        /// </summary>
        private void SelectCharacter(int characterIndex)
        {
            _currentCharacterIndex = characterIndex;

            // PlayerData에 선택한 캐릭터 인덱스 저장
            if (PlayerDataManagerDontdesytoy.Instance != null)
            {
                PlayerDataManagerDontdesytoy.Instance.SelectCharacterIndex = characterIndex;
            }

            // 스킨 UI 업데이트
            UpdateSkinUI(characterIndex);

            LogManager.Log($"캐릭터 선택: {characterIndex}");
        }

        /// <summary>
        /// 스킨 선택 처리
        /// </summary>
        private void SelectSkin(int skinIndex)
        {
            _currentSkinIndex = skinIndex;

            // 선택한 스킨 인덱스 저장
            PlayerPrefs.SetInt("SelectedSkinIndex", skinIndex);
            PlayerPrefs.Save();

            LogManager.Log($"스킨 선택: {skinIndex}");
        }

        /// <summary>
        /// 선택된 캐릭터에 따라 스킨 UI 업데이트
        /// </summary>
        private void UpdateSkinUI(int characterIndex)
        {
            // 기존 스킨 UI 항목 제거
            foreach (var item in _skinIndexItems)
            {
                if (item != null) Destroy(item.gameObject);
            }
            _skinIndexItems.Clear();

            // 선택된 캐릭터의 스킨 UI 다시 생성
            CreateSkinSelectItems(characterIndex);
        }

        #endregion

        #region UI 패널 제어 - 공개 메서드

        /// <summary>
        /// 캐릭터 선택 패널 열기
        /// </summary>
        public void OpenCharacterSelectPanel()
        {
            SetGameObjectActive(characterSelectPanel, true);
            LobbyUIManager.AddClosePopUpAction(CloseCharacterSelectPanel);

            // UI 초기화 - 최신 데이터로 리프레시
            InitializeCharacterUI();
        }

        /// <summary>
        /// 캐릭터 목록 패널 열기
        /// </summary>
        public void OpenCharacterListPanel()
        {
            SetGameObjectActive(characterListPanel, true);
            SetGameObjectActive(characterExpendViewPanel, false);
            LobbyUIManager.AddClosePopUpAction(CloseCharacterListPanel);
        }

        /// <summary>
        /// 캐릭터 스킬 보기 패널 열기
        /// </summary>
        public void OpenCharacterSkinViewPanel()
        {
            SetGameObjectActive(characterExpendViewPanel, true);
            SetGameObjectActive(characterListPanel, false);
            LobbyUIManager.AddClosePopUpAction(CloseCharacterSkinViewPanel);
        }

        /// <summary>
        /// 캐릭터 선택 패널 닫기
        /// </summary>
        public void CloseCharacterSelectPanel()
        {
            SetGameObjectActive(characterSelectPanel, false);
        }

        /// <summary>
        /// 캐릭터 목록 패널 닫기
        /// </summary>
        private void CloseCharacterListPanel()
        {
            SetGameObjectActive(characterListPanel, false);
        }

        /// <summary>
        /// 캐릭터 스킬 보기 패널 닫기
        /// </summary>
        private void CloseCharacterSkinViewPanel()
        {
            SetGameObjectActive(characterExpendViewPanel, false);
        }

        #endregion

        #region 유틸리티 메서드

        /// <summary>
        /// 게임 오브젝트 활성화/비활성화 처리
        /// </summary>
        /// <param name="obj">대상 게임 오브젝트</param>
        /// <param name="isActive">활성화 여부</param>
        private static void SetGameObjectActive(GameObject obj, bool isActive = false)
        {
            if (obj != null)
                obj.SetActive(isActive);
            else
                LogManager.LogWarning("활성화하려는 게임 오브젝트가 null입니다.");
        }

        #endregion

        #region 데이터 클래스

        /// <summary>
        /// 캐릭터 데이터 구조체
        /// </summary>
        [System.Serializable]
        private struct CharacterData
        {
            public int index;         // 캐릭터 번호
            public string name;       // 캐릭터 이름
            public Sprite thumbnail;  // 캐릭터 썸네일
            public bool isUnlocked;   // 잠금 해제 여부
        }

        /// <summary>
        /// 캐릭터 스킨 데이터 구조체
        /// </summary>
        [System.Serializable]
        private struct CharacterSkinData
        {
            public int characterIndex; // 캐릭터 번호
            public int skinIndex;      // 스킨 번호
            public string name;        // 스킨 이름
            public Sprite thumbnail;   // 스킨 썸네일
            public bool isUnlocked;    // 잠금 해제 여부
        }

        #endregion
    }
}

using System.Collections.Generic;
using UnityEngine;
using TMPro;
using UnityEngine.UI;

namespace DogGuns_Games.Lobby
{
    public class ItemSelectManager : MonoBehaviour
    {
        #region 필드 및 변수

        [Header("<color=green>아이템 선택 UI</color>")]
        [SerializeField] private GameObject itemSelectPanel; // 아이템 선택 패널
        [SerializeField] private GameObject itemSelectContainer; // 아이템 선택 컨테이너
        [SerializeField] private Item_Index itemSelectPrefab; // 아이템 선택 프리팹
        [SerializeField] private GameObject itemSelectExtension; // 아이템 선택 확장 패널

        [Header("<color=green>아이템 확장창 UI</color>")]
        [SerializeField] private TMP_Text itemNameText; // 아이템 이름 텍스트
        [SerializeField] private Image itemImage; // 아이템 이미지
        [SerializeField] private TMP_Text itemDescriptionText; // 아이템 설명 텍스트
        [SerializeField] private Button itemSelectButton; // 아이템 선택 버튼

        // 아이템 데이터 관리
        private List<ItemData> _itemDataList = new List<ItemData>();
        private List<Item_Index> _itemIndexList = new List<Item_Index>();
        private int _currentSelectedItemIndex = -1;

        #endregion

        #region Unity 라이프사이클

        private void Awake()
        {
            InitializePanels();
        }

        private void Start()
        {
            LoadItemData();
            InitializeItemUI();

            // 초기 설정
            if (itemSelectButton != null)
            {
                itemSelectButton.onClick.AddListener(SelectCurrentItem);
            }
        }

        #endregion

        #region 초기화 메서드

        /// <summary>
        /// 패널 초기 상태 설정
        /// </summary>
        private void InitializePanels()
        {
            if (itemSelectPanel != null)
                itemSelectPanel.SetActive(false);

            if (itemSelectExtension != null)
                itemSelectExtension.SetActive(false);

            LogManager.Log("아이템 패널 초기화 완료");
        }

        /// <summary>
        /// 아이템 데이터 로드
        /// </summary>
        private void LoadItemData()
        {
            // TODO: 실제 데이터 소스에서 아이템 데이터 로드
            // 임시 데이터 생성
            _itemDataList.Clear();

            // 테스트용 아이템 추가
            _itemDataList.Add(new ItemData
            {
                itemIndex = 0, itemName = "검", itemCode = "W001", itemDescription = "기본 공격력을 증가시키는 무기입니다.",
                itemSprite = null
            });
            _itemDataList.Add(new ItemData
            {
                itemIndex = 1, itemName = "방패", itemCode = "S001", itemDescription = "방어력을 증가시키는 방패입니다.",
                itemSprite = null
            });
            _itemDataList.Add(new ItemData
            {
                itemIndex = 2, itemName = "포션", itemCode = "P001", itemDescription = "체력을 회복시키는 물약입니다.",
                itemSprite = null
            });

            LogManager.Log($"아이템 데이터 {_itemDataList.Count}개 로드 완료");
        }

        /// <summary>
        /// 아이템 UI 초기화
        /// </summary>
        private void InitializeItemUI()
        {
            ClearItemUI();
            CreateItemUI();
        }

        /// <summary>
        /// 기존 아이템 UI 정리
        /// </summary>
        private void ClearItemUI()
        {
            foreach (var item in _itemIndexList)
            {
                if (item != null)
                {
                    Destroy(item.gameObject);
                }
            }

            _itemIndexList.Clear();
        }

        /// <summary>
        /// 아이템 UI 요소 생성
        /// </summary>
        /// <summary>
        /// 아이템 UI 요소 생성
        /// </summary>
        private void CreateItemUI()
        {
            if (itemSelectPrefab == null || itemSelectContainer == null)
            {
                Debug.LogError("아이템 선택 프리팹 또는 컨테이너가 null입니다.");

                return;
            }

            foreach (var itemData in _itemDataList)
            {
                Item_Index itemIndex = Instantiate(itemSelectPrefab, itemSelectContainer.transform);

                // 아이템 데이터 표시
                if (itemIndex.charactorName != null)
                {
                    itemIndex.charactorName.text = itemData.itemName;
                }

                if (itemIndex.thumbNail != null && itemData.itemSprite != null)
                {
                    itemIndex.thumbNail.sprite = itemData.itemSprite;
                }

                // 클릭 이벤트 설정 - 여기에서 아이템 프리팹 클릭 이벤트를 연결합니다
                if (itemIndex.openCharacterSelectButton != null)
                {
                    int index = itemData.itemIndex; // 클로저를 위한 변수
                    itemIndex.openCharacterSelectButton.onClick.RemoveAllListeners(); // 기존 리스너 제거
                    itemIndex.openCharacterSelectButton.onClick.AddListener(() => SelectItem(index));
                    LogManager.Log($"아이템 {itemData.itemName}에 클릭 이벤트 등록 완료");
                }
                else
                {
                    LogManager.LogError($"아이템 {itemData.itemName}의 버튼이 null입니다");
                }

                _itemIndexList.Add(itemIndex);
            }
        }

        #endregion

        #region 아이템 선택 메서드

        /// <summary>
        /// 아이템 선택 처리
        /// </summary>
        /// <summary>
        /// 아이템 선택 처리
        /// </summary>
        private void SelectItem(int itemIndex)
        {
            if (itemIndex < 0 || itemIndex >= _itemDataList.Count)
            {
                LogManager.LogError($"유효하지 않은 아이템 인덱스: {itemIndex}");
                return;
            }

            _currentSelectedItemIndex = itemIndex;

            // 아이템 정보 패널 업데이트 및 표시
            UpdateItemInfoPanel(itemIndex);
            OpenItemExtensionPanel();

            LogManager.Log($"아이템 {itemIndex}번 선택됨: {_itemDataList[itemIndex].itemName}");
        }

        /// <summary>
        /// 현재 선택된 아이템 확정
        /// </summary>
        private void SelectCurrentItem()
        {
            if (_currentSelectedItemIndex >= 0 && _currentSelectedItemIndex < _itemDataList.Count)
            {
                // TODO: 아이템 선택 로직 구현 (플레이어 데이터에 저장 등)

                // 예: PlayerPrefs에 저장
                PlayerPrefs.SetInt("SelectedItemIndex", _currentSelectedItemIndex);
                PlayerPrefs.SetString("SelectedItemCode", _itemDataList[_currentSelectedItemIndex].itemCode);
                PlayerPrefs.Save();

                // 패널 닫기
                CloseItemExtensionPanel();
                CloseItemSelectPanel();

                LogManager.Log($"아이템 선택 완료: {_itemDataList[_currentSelectedItemIndex].itemName}");
            }
            else
            {
                LogManager.LogWarning("선택된 아이템이 없습니다.");
            }
        }

        /// <summary>
        /// 아이템 정보 패널 업데이트
        /// </summary>
        private void UpdateItemInfoPanel(int itemIndex)
        {
            if (itemIndex < 0 || itemIndex >= _itemDataList.Count)
            {
                LogManager.LogError($"유효하지 않은 아이템 인덱스: {itemIndex}");
                return;
            }

            ItemData itemData = _itemDataList[itemIndex];

            // UI 업데이트
            if (itemNameText != null)
                itemNameText.text = itemData.itemName;

            if (itemDescriptionText != null)
                itemDescriptionText.text = itemData.itemDescription;

            if (itemImage != null)
            {
                if (itemData.itemSprite != null)
                    itemImage.sprite = itemData.itemSprite;
                else
                    itemImage.sprite = null; // 기본 이미지 설정
            }
        }

        #endregion

        #region UI 패널 제어 메서드

        /// <summary>
        /// 아이템 선택 패널 열기
        /// </summary>
        public void OpenItemSelectPanel()
        {
            SetGameObjectActive(itemSelectPanel, true);
            SetGameObjectActive(itemSelectExtension, false);

            // 최신 데이터로 UI 리프레시
            InitializeItemUI();

            // 현재 선택된 아이템 초기화
            _currentSelectedItemIndex = -1;

            // 팝업 액션 등록
            LobbyUIManager.AddClosePopUpAction(CloseItemSelectPanel);

            LogManager.Log("아이템 선택 패널 열림");
        }

        /// <summary>
        /// 아이템 확장 패널 열기
        /// </summary>
        private void OpenItemExtensionPanel()
        {
            if (itemSelectExtension != null)
            {
                itemSelectExtension.SetActive(true);

                // 팝업 액션 등록
                LobbyUIManager.AddClosePopUpAction(CloseItemExtensionPanel);

                LogManager.Log("아이템 확장 패널 열림");
            }
            else
            {
                LogManager.LogError("아이템 확장 패널이 null입니다");
            }
        }

        /// <summary>
        /// 아이템 선택 패널 닫기
        /// </summary>
        public void CloseItemSelectPanel()
        {
            SetGameObjectActive(itemSelectPanel, false);
            LogManager.Log("아이템 선택 패널 닫힘");
        }

        /// <summary>
        /// 아이템 확장 패널 닫기
        /// </summary>
        private void CloseItemExtensionPanel()
        {
            SetGameObjectActive(itemSelectExtension, false);
            LogManager.Log("아이템 확장 패널 닫힘");
        }

        #endregion

        #region 유틸리티 메서드

        /// <summary>
        /// 게임 오브젝트 활성화/비활성화 처리
        /// </summary>
        private static void SetGameObjectActive(GameObject obj, bool isActive = false)
        {
            if (obj != null)
                obj.SetActive(isActive);
            else
                LogManager.LogWarning("활성화하려는 게임 오브젝트가 null입니다.");
        }

        #endregion

        #region 데이터 구조체

        /// <summary>
        /// 아이템 데이터 구조체
        /// </summary>
        [System.Serializable]
        private struct ItemData
        {
            public int itemIndex; // 아이템 번호
            public string itemName; // 아이템 이름
            public string itemCode; // 아이템 코드
            public string itemDescription; // 아이템 설명
            public Sprite itemSprite; // 아이템 이미지
        }

        #endregion
    }
}

using System.Collections.Generic;
using UnityEngine;
using TMPro;
using UnityEngine.UI;

namespace DogGuns_Games.Lobby
{
    public class ItemSelectManager : MonoBehaviour
    {
        #region 필드 및 변수

        [Header("<color=green>아이템 선택 UI</color>")]
        [SerializeField] private GameObject itemSelectPanel; // 아이템 선택 패널
        [SerializeField] private GameObject itemSelectContainer; // 아이템 선택 컨테이너
        [SerializeField] private Item_Index itemSelectPrefab; // 아이템 선택 프리팹
        [SerializeField] private GameObject itemSelectExtension; // 아이템 선택 확장 패널

        [Header("<color=green>아이템 확장창 UI</color>")]
        [SerializeField] private TMP_Text itemNameText; // 아이템 이름 텍스트
        [SerializeField] private Image itemImage; // 아이템 이미지
        [SerializeField] private TMP_Text itemDescriptionText; // 아이템 설명 텍스트
        [SerializeField] private Button itemSelectButton; // 아이템 선택 버튼

        // 아이템 데이터 관리
        private List<ItemData> _itemDataList = new List<ItemData>();
        private List<Item_Index> _itemIndexList = new List<Item_Index>();
        private int _currentSelectedItemIndex = -1;

        #endregion

        #region Unity 라이프사이클

        private void Awake()
        {
            InitializePanels();
        }

        private void Start()
        {
            LoadItemData();
            InitializeItemUI();

            // 초기 설정
            if (itemSelectButton != null)
            {
                itemSelectButton.onClick.AddListener(SelectCurrentItem);
            }
        }

        #endregion

        #region 초기화 메서드

        /// <summary>
        /// 패널 초기 상태 설정
        /// </summary>
        private void InitializePanels()
        {
            if (itemSelectPanel != null)
                itemSelectPanel.SetActive(false);

            if (itemSelectExtension != null)
                itemSelectExtension.SetActive(false);

            LogManager.Log("아이템 패널 초기화 완료");
        }

        /// <summary>
        /// 아이템 데이터 로드
        /// </summary>
        private void LoadItemData()
        {
            // TODO: 실제 데이터 소스에서 아이템 데이터 로드
            // 임시 데이터 생성
            _itemDataList.Clear();

            // 테스트용 아이템 추가
            _itemDataList.Add(new ItemData
            {
                itemIndex = 0, itemName = "검", itemCode = "W001", itemDescription = "기본 공격력을 증가시키는 무기입니다.",
                itemSprite = null
            });
            _itemDataList.Add(new ItemData
            {
                itemIndex = 1, itemName = "방패", itemCode = "S001", itemDescription = "방어력을 증가시키는 방패입니다.",
                itemSprite = null
            });
            _itemDataList.Add(new ItemData
            {
                itemIndex = 2, itemName = "포션", itemCode = "P001", itemDescription = "체력을 회복시키는 물약입니다.",
                itemSprite = null
            });

            LogManager.Log($"아이템 데이터 {_itemDataList.Count}개 로드 완료");
        }

        /// <summary>
        /// 아이템 UI 초기화
        /// </summary>
        private void InitializeItemUI()
        {
            ClearItemUI();
            CreateItemUI();
        }

        /// <summary>
        /// 기존 아이템 UI 정리
        /// </summary>
        private void ClearItemUI()
        {
            foreach (var item in _itemIndexList)
            {
                if (item != null)
                {
                    Destroy(item.gameObject);
                }
            }

            _itemIndexList.Clear();
        }

        /// <summary>
        /// 아이템 UI 요소 생성
        /// </summary>
        /// <summary>
        /// 아이템 UI 요소 생성
        /// </summary>
        private void CreateItemUI()
        {
            if (itemSelectPrefab == null || itemSelectContainer == null)
            {
                LogManager.LogError("아이템 선택 프리팹 또는 컨테이너가 null입니다.");
                return;
            }

            foreach (var itemData in _itemDataList)
            {
                Item_Index itemIndex = Instantiate(itemSelectPrefab, itemSelectContainer.transform);

                // 아이템 데이터 표시
                if (itemIndex.charactorName != null)
                {
                    itemIndex.charactorName.text = itemData.itemName;
                }

                if (itemIndex.thumbNail != null && itemData.itemSprite != null)
                {
                    itemIndex.thumbNail.sprite = itemData.itemSprite;
                }

                // 클릭 이벤트 설정 - 여기에서 아이템 프리팹 클릭 이벤트를 연결합니다
                if (itemIndex.openCharacterSelectButton != null)
                {
                    int index = itemData.itemIndex; // 클로저를 위한 변수
                    itemIndex.openCharacterSelectButton.onClick.RemoveAllListeners(); // 기존 리스너 제거
                    itemIndex.openCharacterSelectButton.onClick.AddListener(() => SelectItem(index));
                    LogManager.Log($"아이템 {itemData.itemName}에 클릭 이벤트 등록 완료");
                }
                else
                {
                    LogManager.LogError($"아이템 {itemData.itemName}의 버튼이 null입니다");
                }

                _itemIndexList.Add(itemIndex);
            }
        }

        #endregion

        #region 아이템 선택 메서드

        /// <summary>
        /// 아이템 선택 처리
        /// </summary>
        /// <summary>
        /// 아이템 선택 처리
        /// </summary>
        private void SelectItem(int itemIndex)
        {
            if (itemIndex < 0 || itemIndex >= _itemDataList.Count)
            {
                LogManager.LogError($"유효하지 않은 아이템 인덱스: {itemIndex}");
                return;
            }

            _currentSelectedItemIndex = itemIndex;

            // 아이템 정보 패널 업데이트 및 표시
            UpdateItemInfoPanel(itemIndex);
            OpenItemExtensionPanel();

            LogManager.Log($"아이템 {itemIndex}번 선택됨: {_itemDataList[itemIndex].itemName}");
        }

        /// <summary>
        /// 현재 선택된 아이템 확정
        /// </summary>
        private void SelectCurrentItem()
        {
            if (_currentSelectedItemIndex >= 0 && _currentSelectedItemIndex < _itemDataList.Count)
            {
                // TODO: 아이템 선택 로직 구현 (플레이어 데이터에 저장 등)

                // 예: PlayerPrefs에 저장
                PlayerPrefs.SetInt("SelectedItemIndex", _currentSelectedItemIndex);
                PlayerPrefs.SetString("SelectedItemCode", _itemDataList[_currentSelectedItemIndex].itemCode);
                PlayerPrefs.Save();

                // 패널 닫기
                CloseItemExtensionPanel();
                CloseItemSelectPanel();

                LogManager.Log($"아이템 선택 완료: {_itemDataList[_currentSelectedItemIndex].itemName}");
            }
            else
            {
                LogManager.LogWarning("선택된 아이템이 없습니다.");
            }
        }

        /// <summary>
        /// 아이템 정보 패널 업데이트
        /// </summary>
        private void UpdateItemInfoPanel(int itemIndex)
        {
            if (itemIndex < 0 || itemIndex >= _itemDataList.Count)
            {
                LogManager.LogError($"유효하지 않은 아이템 인덱스: {itemIndex}");
                return;
            }

            ItemData itemData = _itemDataList[itemIndex];

            // UI 업데이트
            if (itemNameText != null)
                itemNameText.text = itemData.itemName;

            if (itemDescriptionText != null)
                itemDescriptionText.text = itemData.itemDescription;

            if (itemImage != null)
            {
                if (itemData.itemSprite != null)
                    itemImage.sprite = itemData.itemSprite;
                else
                    itemImage.sprite = null; // 기본 이미지 설정
            }
        }

        #endregion

        #region UI 패널 제어 메서드

        /// <summary>
        /// 아이템 선택 패널 열기
        /// </summary>
        public void OpenItemSelectPanel()
        {
            SetGameObjectActive(itemSelectPanel, true);
            SetGameObjectActive(itemSelectExtension, false);

            // 최신 데이터로 UI 리프레시
            InitializeItemUI();

            // 현재 선택된 아이템 초기화
            _currentSelectedItemIndex = -1;

            // 팝업 액션 등록
            LobbyUIManager.AddClosePopUpAction(CloseItemSelectPanel);

            LogManager.Log("아이템 선택 패널 열림");
        }

        /// <summary>
        /// 아이템 확장 패널 열기
        /// </summary>
        private void OpenItemExtensionPanel()
        {
            if (itemSelectExtension != null)
            {
                itemSelectExtension.SetActive(true);

                // 팝업 액션 등록
                LobbyUIManager.AddClosePopUpAction(CloseItemExtensionPanel);

                LogManager.Log("아이템 확장 패널 열림");
            }
            else
            {
                LogManager.LogError("아이템 확장 패널이 null입니다");
            }
        }

        /// <summary>
        /// 아이템 선택 패널 닫기
        /// </summary>
        public void CloseItemSelectPanel()
        {
            SetGameObjectActive(itemSelectPanel, false);
            LogManager.Log("아이템 선택 패널 닫힘");
        }

        /// <summary>
        /// 아이템 확장 패널 닫기
        /// </summary>
        private void CloseItemExtensionPanel()
        {
            SetGameObjectActive(itemSelectExtension, false);
            LogManager.Log("아이템 확장 패널 닫힘");
        }

        #endregion

        #region 유틸리티 메서드

        /// <summary>
        /// 게임 오브젝트 활성화/비활성화 처리
        /// </summary>
        private static void SetGameObjectActive(GameObject obj, bool isActive = false)
        {
            if (obj != null)
                obj.SetActive(isActive);
            else
                LogManager.LogWarning("활성화하려는 게임 오브젝트가 null입니다.");
        }

        #endregion

        #region 데이터 구조체

        /// <summary>
        /// 아이템 데이터 구조체
        /// </summary>
        [System.Serializable]
        private struct ItemData
        {
            public int itemIndex; // 아이템 번호
            public string itemName; // 아이템 이름
            public string itemCode; // 아이템 코드
            public string itemDescription; // 아이템 설명
            public Sprite itemSprite; // 아이템 이미지
        }

        #endregion
    }
}

using TMPro;
using UnityEngine;

namespace DogGuns_Games.Lobby
{
    /// <summary>
    /// 게임 내 우편 시스템을 관리하는 클래스
    /// </summary>
    public class PostManager : MonoBehaviour
    {
        #region 데이터 구조

        /// <summary>
        /// 우편 메시지 데이터 구조체
        /// </summary>
        private struct PostMessage
        {
            public string Message;
            public string Sender;
            public string Date;
            public int ItemCode;
            public string RewardItemName;
        }

        #endregion

        #region 우편함 UI 요소

        [Header("<color=green>우편함 기본 UI")]
        [SerializeField] private GameObject postBoxPanel;
        [SerializeField] private GameObject postboxContainer;
        [SerializeField] private PostIndex postboxPrefab;

        [Header("<color=green>우편함 상세 UI")]
        [SerializeField] private GameObject postBoxPanelExtension;
        [SerializeField] private TMP_Text postBoxPanelExtensionText;
        [SerializeField] private TMP_Text postBoxSendernameText;
        [SerializeField] private TMP_Text rewardItemNameText;

        #endregion

        #region 데이터 필드

        /// <summary>
        /// 현재 선택된 아이템 코드
        /// </summary>
        private int _currentItemCode;

        #endregion

        #region Unity 라이프사이클

        private void Start()
        {
            InitializePostSystem();
        }

        #endregion

        #region 초기화

        /// <summary>
        /// 우편 시스템 초기화
        /// </summary>
        private void InitializePostSystem()
        {
            // UI 초기 상태 설정
            if (postBoxPanel != null)
                postBoxPanel.SetActive(false);

            if (postBoxPanelExtension != null)
                postBoxPanelExtension.SetActive(false);

            // 테스트용 우편 생성
            AddPostSample();
        }

        /// <summary>
        /// 샘플 우편 데이터 추가 (개발/테스트용)
        /// </summary>
        private void AddPostSample()
        {
            // 샘플 우편 추가
            AddPostItem("게임 출시 기념 선물", "운영팀", "2023-11-01", "골드 1000개", 1001);
            AddPostItem("이벤트 보상", "이벤트팀", "2023-11-02", "다이아몬드 50개", 1002);
        }

        #endregion

        #region 우편함 UI 관리

        /// <summary>
        /// 우편함 메인 패널 열기
        /// </summary>
        public void OpenPostBoxPanel()
        {
            if (postBoxPanel == null)
            {
                Debug.LogError("우편함 패널이 설정되지 않았습니다.");
                return;
            }

            postBoxPanel.SetActive(true);
            LobbyUIManager.AddClosePopUpAction(ClosePostBoxPanel);
            Debug.Log("우편함 패널 열림");
        }

        /// <summary>
        /// 우편함 메인 패널 닫기
        /// </summary>
        private void ClosePostBoxPanel()
        {
            if (postBoxPanel == null) return;

            postBoxPanel.SetActive(false);
            Debug.Log("우편함 패널 닫힘");
        }

        /// <summary>
        /// 우편 상세 패널 열기
        /// </summary>
        private void OpenPostBoxPanel_Extension(string message, string sender, string rewardItemName, int itemCode)
        {
            if (postBoxPanelExtension == null)
            {
                Debug.LogError("우편함 상세 패널이 설정되지 않았습니다.");
                return;
            }

            // 상세 패널 UI 업데이트
            postBoxPanelExtension.SetActive(true);

            if (postBoxPanelExtensionText != null)
                postBoxPanelExtensionText.text = message;

            if (postBoxSendernameText != null)
                postBoxSendernameText.text = sender;

            if (rewardItemNameText != null)
                rewardItemNameText.text = rewardItemName;

            // 아이템 코드 저장 및 팝업 닫기 액션 등록
            _currentItemCode = itemCode;
            LobbyUIManager.AddClosePopUpAction(ClosePostBoxPanel_Extension);

            Debug.Log($"우편 상세 열림: {sender}로부터의 메시지, 아이템 코드: {itemCode}");
        }

        /// <summary>
        /// 우편 상세 패널 닫기
        /// </summary>
        private void ClosePostBoxPanel_Extension()
        {
            if (postBoxPanelExtension == null) return;

            postBoxPanelExtension.SetActive(false);
            Debug.Log("우편 상세 패널 닫힘");
        }

        #endregion

        #region 우편 데이터 관리

        /// <summary>
        /// 우편 아이템 추가 및 UI 이벤트 설정
        /// </summary>
        /// <param name="message">우편 내용</param>
        /// <param name="sender">발신자</param>
        /// <param name="date">발송 날짜</param>
        /// <param name="rewardItemName">보상 아이템 이름</param>
        /// <param name="itemCode">보상 아이템 코드</param>
        private void AddPostItem(string message, string sender, string date, string rewardItemName, int itemCode)
        {
            // 필수 컴포넌트 확인
            if (postboxPrefab == null || postboxContainer == null)
            {
                Debug.LogError("우편함 프리팹 또는 컨테이너가 설정되지 않았습니다.");
                return;
            }

            // 우편 인덱스 생성
            PostIndex postIndex = Instantiate(postboxPrefab, postboxContainer.transform);
            if (postIndex == null)
            {
                Debug.LogError("우편함 프리팹 생성 실패!");
                return;
            }

            // 이벤트 설정
            UnityEngine.Events.UnityEvent clickEvent = new UnityEngine.Events.UnityEvent();
            clickEvent.AddListener(() => OpenPostBoxPanel_Extension(message, sender, rewardItemName, itemCode));

            UnityEngine.Events.UnityEvent rewardEvent = new UnityEngine.Events.UnityEvent();
            rewardEvent.AddListener(() => ConfiromReword(itemCode));

            // 우편 인덱스 초기화
            postIndex.SetPostIndex(sender, message, date, rewardEvent, clickEvent);

            LogManager.Log($"우편 추가됨: {sender}로부터 {date}에 받은 메시지, 보상: {rewardItemName}");
        }

        /// <summary>
        /// 보상 수령 처리
        /// </summary>
        public void Getreward()
        {
            if (_currentItemCode <= 0)
            {
                LogManager.LogWarning("유효하지 않은 아이템 코드입니다.");
                return;
            }

            ConfiromReword(_currentItemCode);
            LogManager.Log($"보상 수령: 아이템 코드 {_currentItemCode}");
        }

        /// <summary>
        /// 보상 수령 확인 및 처리
        /// </summary>
        /// <param name="itemCode">수령할 아이템 코드</param>
        private void ConfiromReword(int itemCode)
        {
            if (InventoryDataManagerDontdestory.Instance == null)
            {
                LogManager.LogError("인벤토리 데이터 매니저가 설정되지 않았습니다.");
                return;
            }

            InventoryDataManagerDontdestory.Instance.GetItemByItemCode(itemCode);
            LogManager.Log($"아이템 코드 {itemCode} 아이템이 인벤토리에 추가되었습니다.");
        }

        #endregion
    }
}

