            // 샘플 우편 추가
            AddPostItem("게임 출시 기념 선물", "운영팀", "2023-11-01", "골드 1000개", 1001);
            AddPostItem("이벤트 보상", "이벤트팀", "2023-11-02", "다이아몬드 50개", 1002);
        }

        #endregion

        #region 우편함 UI 관리

        /// <summary>
        /// 우편함 메인 패널 열기
        /// </summary>
        public void OpenPostBoxPanel()
        {
            if (postBoxPanel == null)
            {
                LogManager.LogError("우편함 패널이 설정되지 않았습니다.");
                return;
            }

            postBoxPanel.SetActive(true);
            LobbyUIManager.AddClosePopUpAction(ClosePostBoxPanel);
            LogManager.Log("우편함 패널 열림");
        }

        /// <summary>
        /// 우편함 메인 패널 닫기
        /// </summary>
        private void ClosePostBoxPanel()
        {
            if (postBoxPanel == null) return;
            postBoxPanel.SetActive(false);
            LogManager.Log("우편함 패널 닫힘");
        }

        /// <summary>
        /// 우편 상세 패널 열기
        /// </summary>
        private void OpenPostBoxPanel_Extension(string message, string sender, string rewardItemName, int itemCode)
        {
            if (postBoxPanelExtension == null)
            {
                LogManager.LogError("우편함 상세 패널이 설정되지 않았습니다.");
                return;
            }

            postBoxPanelExtension.SetActive(true);
            if (postBoxPanelExtensionText != null)
                postBoxPanelExtensionText.text = message;
            if (postBoxSendernameText != null)
                postBoxSendernameText.text = sender;
            if (rewardItemNameText != null)
                rewardItemNameText.text = rewardItemName;
            _currentItemCode = itemCode;
            LobbyUIManager.AddClosePopUpAction(ClosePostBoxPanel_Extension);
            LogManager.Log($"우편 상세 열림: {sender}로부터의 메시지, 아이템 코드: {itemCode}");
        }

        /// <summary>
        /// 우편 상세 패널 닫기
        /// </summary>
        private void ClosePostBoxPanel_Extension()
        {
            if (postBoxPanelExtension == null) return;
            postBoxPanelExtension.SetActive(false);
            LogManager.Log("우편 상세 패널 닫힘");
        }

        #endregion

        #region 우편 데이터 관리

        /// <summary>
        /// 우편 아이템 추가 및 UI 이벤트 설정
        /// </summary>
        /// <param name="message">우편 내용</param>
        /// <param name="sender">발신자</param>
        /// <param name="date">발송 날짜</param>
        /// <param name="rewardItemName">보상 아이템 이름</param>
        /// <param name="itemCode">보상 아이템 코드</param>
        private void AddPostItem(string message, string sender, string date, string rewardItemName, int itemCode)
        {
            if (postboxPrefab == null || postboxContainer == null)
            {
                LogManager.LogError("우편함 프리팹 또는 컨테이너가 설정되지 않았습니다.");
                return;
            }

            PostIndex postIndex = Instantiate(postboxPrefab, postboxContainer.transform);
            if (postIndex == null)
            {
                LogManager.LogError("우편함 프리팹 생성 실패!");
                return;
            }

            // 이벤트 설정
            UnityEngine.Events.UnityEvent clickEvent = new UnityEngine.Events.UnityEvent();
            clickEvent.AddListener(() => OpenPostBoxPanel_Extension(message, sender, rewardItemName, itemCode));

            UnityEngine.Events.UnityEvent rewardEvent = new UnityEngine.Events.UnityEvent();
            rewardEvent.AddListener(() => ConfiromReword(itemCode));

            // 우편 인덱스 초기화
            postIndex.SetPostIndex(sender, message, date, rewardEvent, clickEvent);

            LogManager.Log($"우편 추가됨: {sender}로부터 {date}에 받은 메시지, 보상: {rewardItemName}");
        }

        /// <summary>
        /// 보상 수령 처리
        /// </summary>
        public void Getreward()
        {
            if (_currentItemCode <= 0)
            {
                LogManager.LogWarning("유효하지 않은 아이템 코드입니다.");
                return;
            }

            ConfiromReword(_currentItemCode);
            LogManager.Log($"보상 수령: 아이템 코드 {_currentItemCode}");
        }

        /// <summary>
        /// 보상 수령 확인 및 처리
        /// </summary>
        /// <param name="itemCode">수령할 아이템 코드</param>
        private void ConfiromReword(int itemCode)
        {
            if (InventoryDataManagerDontdestory.Instance == null)
            {
                LogManager.LogError("인벤토리 데이터 매니저가 설정되지 않았습니다.");
                return;
            }

            InventoryDataManagerDontdestory.Instance.GetItemByItemCode(itemCode);
            LogManager.Log($"아이템 코드 {itemCode} 아이템이 인벤토리에 추가되었습니다.");
        }

        #endregion
    }
}

using System.Collections;
using System.Collections.Generic;
using UnityEngine;
using UnityEngine.SceneManagement;
using UnityEngine.UI;

namespace DogGuns_Games
{
    public class SceneLoader : MonoBehaviour
    {
        protected static SceneLoader instance;

        // 씬 이름 상수들
        public const string INTRO_SCENE = "IntroScene";
        public const string LOBBY_SCENE = "LobbyScene";
        public const string RUN_GAME_SCENE = "RunGame";
        public const string VAMSER_LIKE_SCENE = "VamSerlike";

        public static SceneLoader Instance // 오타 수정: Instace -> Instance
        {
            get
            {
                if (instance == null)
                {
                    var obj = FindAnyObjectByType<SceneLoader>();
                    if (obj != null)
                    {
                        instance = obj;
                    }
                    else
                    {
                        instance = Create();
                    }
                }

                return instance;
            }
            private set { instance = value; }
        }

        [SerializeField] private CanvasGroup sceneLoadferCanvasGroup;
        [SerializeField] private Slider progressbar;

        [Header("Scene References")]
        [SerializeField] private SceneReference[] sceneReferences;

        [System.Serializable]
        public class SceneReference
        {
            public string sceneName;

            #if UNITY_EDITOR
            [SerializeField] private UnityEditor.SceneAsset sceneAsset;

            public UnityEditor.SceneAsset SceneAsset
            {
                get => sceneAsset;
                set
                {
                    sceneAsset = value;
                    sceneName = sceneAsset != null ? sceneAsset.name : "";
                }
            }
            #endif
        }


        private string loadSceneName;

        public static SceneLoader Create(SceneLoader prefab = null)
        {
            var SeneLoadprefeb = Resources.Load<SceneLoader>("SceneLoader");
            return Instantiate(SeneLoadprefeb);
        }

        private void Awake()
        {
            if (instance != this)
            {
                Destroy(gameObject);
                return;
            }

            DontDestroyOnLoad(gameObject);
        }

        /// <summary>
        /// 로비 씬으로 이동합니다.
        /// </summary>
        public void LoadLobbyScene()
        {
            LoadScene(LOBBY_SCENE);
        }

        /// <summary>
        /// 게임 씬으로 이동합니다.
        /// </summary>
        public void LoadGameScene()
        {
            LoadScene(RUN_GAME_SCENE);
        }

        /// <summary>
        /// VamSerLike 씬으로 이동합니다.
        /// </summary>
        public void LoadVamSerLikeScene()
        {
            LoadScene(VAMSER_LIKE_SCENE);
        }

        /// <summary>
        /// 인트로 씬으로 이동합니다.
        /// </summary>
        public void LoadIntroScene()
        {
            LoadScene(INTRO_SCENE);
        }

        public void LoadScene(string SceneName)
        {
            // 씬이 빌드에 포함되어 있는지 확인
            if (!IsSceneInBuild(SceneName))
            {
                Debug.LogError($"씬 '{SceneName}'이 빌드 설정에 포함되어 있지 않습니다!");
                return;
            }

            gameObject.SetActive(true);
            SceneManager.sceneLoaded += LoadSceneEnd;
            loadSceneName = SceneName;
            StartCoroutine(Load(SceneName));
            Debug.Log($"씬 변경 시작: {SceneName}");
        }

        /// <summary>
        /// 씬이 빌드에 포함되어 있는지 확인합니다.
        /// </summary>
        private bool IsSceneInBuild(string sceneName)
        {
            for (int i = 0; i < SceneManager.sceneCountInBuildSettings; i++)
            {
                string scenePath = SceneUtility.GetScenePathByBuildIndex(i);
                string sceneNameInBuild = System.IO.Path.GetFileNameWithoutExtension(scenePath);
                if (sceneNameInBuild == sceneName)
                {
                    return true;
                }
            }
            return false;
        }

        /// <summary>
        /// SceneReference를 통해 씬을 로드합니다.
        /// </summary>
        public void LoadScene(SceneReference sceneRef)
        {
            if (sceneRef != null && !string.IsNullOrEmpty(sceneRef.sceneName))
            {
                LoadScene(sceneRef.sceneName);
            }
            else
            {
                Debug.LogError("SceneReference가 유효하지 않습니다!");
            }
        }


        /// <summary>
        /// 씬 이름으로 SceneReference를 찾습니다.
        /// </summary>
        public SceneReference FindSceneReference(string sceneName)
        {
            if (sceneReferences != null)
            {
                foreach (var sceneRef in sceneReferences)
                {
                    if (sceneRef.sceneName == sceneName)
                        return sceneRef;
                }
            }
            return null;
        }

        private IEnumerator Load(string sceneName)
        {
            progressbar.value = 0f;
            yield return StartCoroutine(Fade(true));

            AsyncOperation op = SceneManager.LoadSceneAsync(sceneName);
            op.allowSceneActivation = false;

            float timer = 0.0f;
            while (!op.isDone)
            {
                yield return null;
                timer += Time.unscaledDeltaTime;
                if (op.progress < 0.9f)
                {
                    float targetProgress = Mathf.Lerp(progressbar.value, op.progress, timer);
                    progressbar.value = targetProgress;
                    if (progressbar.value >= op.progress)
                    {
                        timer = 0f;
                    }
                }
                else
                {
                    float targetProgress = Mathf.Lerp(progressbar.value, 1f, timer);
                    progressbar.value = targetProgress;
                    if (progressbar.value >= 0.9999f)
                    {
                        op.allowSceneActivation = true;
                        yield break;
                    }
                }
            }
        }


        private void LoadSceneEnd(Scene scene, LoadSceneMode loadSceneMode)
        {
            if (scene.name == loadSceneName)
            {
                StartCoroutine(Fade(false));
                SceneManager.sceneLoaded -= LoadSceneEnd;
            }
        }

        private IEnumerator Fade(bool isFadeIn)
        {
            float timer = 0f;

            while (timer <= 1f)
            {
                yield return null;
                timer += Time.unscaledDeltaTime * 2f;
                sceneLoadferCanvasGroup.alpha = Mathf.Lerp(isFadeIn ? 0 : 1, isFadeIn ? 1 : 0, timer);
            }

            if (!isFadeIn)
            {
                gameObject.SetActive(false);
            }
        }
    }
}

