using System.Collections.Generic;
using System.IO;
using BackEnd;
using BackEnd.BackndNewtonsoft.Json;
using UnityEngine;
using System;
using System.Linq;

namespace DogGuns_Games.Lobby
{
    /// <summary>
    /// 인벤토리 데이터를 관리하고 암호화하여 저장/로드하는 매니저 클래스
    /// DontDestroyOnLoad로 씬 전환 시에도 유지됩니다.
    /// </summary>
    public class InventoryDataManagerDontdestory : MonoBehaviour
    {
        #region 필드 및 변수

        [SerializeField] private TextAsset itemDataJsonFile;
        public Inventory_Data scritpableobjInventoryData;
        public string inventorydataString;

        private HybridEncryption _encryption;
        private string _localSavePath;

        // 캐시 필드
        private Item_Data _currentItemData;
        private Dictionary<int, Item_Data> _itemDataCache = new Dictionary<int, Item_Data>();
        private bool _isDataLoaded = false;

        #endregion

        #region 싱글톤 패턴

        private static InventoryDataManagerDontdestory _instance;
        private static readonly object LockObject = new object();

        public static InventoryDataManagerDontdestory Instance
        {
            get
            {
                if (_instance == null)
                {
                    lock (LockObject) // 스레드 안전성 보장
                    {
                        if (_instance == null)
                        {
                            _instance = FindAnyObjectByType<InventoryDataManagerDontdestory>();
                            if (_instance == null)
                            {
                                var container = new GameObject("InventoryDataManager");
                                _instance = container.AddComponent<InventoryDataManagerDontdestory>();
                                DontDestroyOnLoad(container);
                                LogManager.Log("인벤토리 데이터 매니저 인스턴스가 생성되었습니다.", "InventoryManager");
                            }
                        }
                    }
                }

                return _instance;
            }
        }

        #endregion

        #region Unity 라이프사이클

        private void Awake()
        {
            // 싱글톤 패턴 구현
            if (Instance != this)
            {
                Destroy(gameObject);
                return;
            }

            DontDestroyOnLoad(gameObject);

            // 초기화
            _encryption = new HybridEncryption();
            _localSavePath = Path.Combine(Application.persistentDataPath, "inventoryData.encrypted");

            // Inventory_Data 초기화
            if (scritpableobjInventoryData == null)
                scritpableobjInventoryData = ScriptableObject.CreateInstance<Inventory_Data>();
        }

        private void Start()
        {
            LoadItemDataFromJson();

            if (!_isDataLoaded)
            {
                LogManager.LogWarning("JSON에서 아이템 데이터를 불러오지 못했습니다.", "InventoryManager");
            }

            // 서버에서 인벤토리 데이터 로드
            LoadDataFromServer();
        }

        #endregion

        #region 초기화 및 데이터 로드

        /// <summary>
        /// 기본 인벤토리 데이터를 생성합니다.
        /// </summary>
        private void CreateDefaultInventory()
        {
            try
            {
                LogManager.Log("새 인벤토리 데이터를 생성합니다.", LogManager.LogCategory.InventoryManager);

                // 인벤토리 데이터가 이미 초기화되어 있는지 확인
                if (scritpableobjInventoryData == null)
                {
                    scritpableobjInventoryData = ScriptableObject.CreateInstance<Inventory_Data>();
                }
                else
                {
                    scritpableobjInventoryData.InitInventory();
                }

                // 기본 아이템 추가 (필요한 경우)
                // 예: 시작용 기본 장비 추가
                if (_isDataLoaded && _itemDataCache.Count > 0)
                {
                    // 아이템 목록에서 첫 번째 아이템을 기본 아이템으로 추가 (예시)
                    var defaultItemCode = _itemDataCache.Keys.First();
                    var defaultItem = _itemDataCache[defaultItemCode];

                    scritpableobjInventoryData.AddItem(defaultItem);
                    LogManager.Log($"기본 아이템 추가: {defaultItem.itemName} (코드: {defaultItem.itemCode})", "InventoryManager");
                }

                // 인벤토리 JSON 문자열 생성
                inventorydataString = JsonConvert.SerializeObject(scritpableobjInventoryData, Formatting.Indented);

                // 로컬에 저장
                SaveInventoryData();

                // 서버에 저장
                UploadDataToServer();
            }
            catch (System.Exception ex)
            {
                LogManager.LogError($"기본 인벤토리 생성 중 오류 발생: {ex.Message}", LogManager.LogCategory.InventoryManager);
            }
        }

        /// <summary>
        /// JSON 파일에서 아이템 데이터를 로드합니다.
        /// </summary>
        private void LoadItemDataFromJson()
        {
            if (itemDataJsonFile == null)
            {
                LogManager.LogError("아이템 데이터 JSON 파일이 인스펙터에서 할당되지 않았습니다.", "InventoryManager");
                return;
            }

            try
            {
                JsonItemData[] jsonItems = JsonConvert.DeserializeObject<JsonItemData[]>(itemDataJsonFile.text);

                if (jsonItems == null || jsonItems.Length == 0)
                {
                    LogManager.LogWarning("JSON 데이터에서 아이템을 찾을 수 없습니다.", "InventoryManager");
                    return;
                }

                _itemDataCache.Clear();

                foreach (var jsonItem in jsonItems)
                {
                    Item_Data itemData = ScriptableObject.CreateInstance<Item_Data>();
                    itemData.itemName = jsonItem.itemName;
                    itemData.itemCode = jsonItem.itemCode;
                    itemData.itemtype = jsonItem.itemtype;
                    itemData.itemCount = jsonItem.itemCount;
                    itemData.itemcoinType = jsonItem.itemcoinType;
                    itemData.itemcoinCount = jsonItem.itemcoinCount;

                    _itemDataCache[itemData.itemCode] = itemData;
                }

                _isDataLoaded = true;
                LogManager.Log($"JSON 데이터에서 {_itemDataCache.Count}개의 아이템을 성공적으로 로드했습니다.", "InventoryManager");
            }
            catch (Exception e)
            {
                LogManager.LogError($"JSON 데이터 파싱 오류: {e.Message}", "InventoryManager");
            }
        }

        #endregion

        #region 인벤토리 및 아이템 관리

        /// <summary>
        /// 아이템 코드로 아이템 데이터를 가져옵니다.
        /// </summary>
        /// <param name="itemCode">찾을 아이템의 코드</param>
        /// <returns>아이템 데이터 또는 null</returns>
        public Item_Data GetItemByItemCode(int itemCode)
        {
            if (!_isDataLoaded)
            {
                LogManager.LogWarning("아이템 데이터가 아직 로드되지 않았습니다.", "InventoryManager");
                return null;
            }

            if (_itemDataCache.TryGetValue(itemCode, out Item_Data item))
            {
                _currentItemData = item;
                return item;
            }

            LogManager.LogWarning($"코드 {itemCode}를 가진 아이템을 찾을 수 없습니다.", "InventoryManager");
            return null;
        }

        /// <summary>
        /// 인벤토리 데이터를 업데이트합니다.
        /// </summary>
        /// <param name="inventoryData">새로운 인벤토리 데이터</param>
        public void Update_Inventory_Data(Inventory_Data inventoryData)
        {
            if (inventoryData == null)
            {
                LogManager.LogWarning("업데이트할 인벤토리 데이터가 null입니다.", "InventoryManager");
                return;
            }
            scritpableobjInventoryData = inventoryData;
            try
            {
                inventorydataString = JsonConvert.SerializeObject(scritpableobjInventoryData, Formatting.Indented);
#if UNITY_EDITOR
                LogManager.Log("<color=green>인벤토리 데이터 업데이트 완료</color>", "InventoryManager");
                LogManager.Log($"인벤토리 데이터: {inventorydataString}", "InventoryManager");
#endif
            }
            catch (Exception ex)
            {
                LogManager.LogError($"인벤토리 데이터 직렬화 중 오류: {ex.Message}", "InventoryManager");
            }
            SaveInventoryData();
        }

        /// <summary>
        /// 현재 선택된 아이템 데이터를 업데이트합니다.
        /// </summary>
        /// <param name="itemData">업데이트할 아이템 데이터</param>
        public void UpdateItemData(Item_Data itemData)
        {
            if (itemData == null)
            {
                LogManager.LogWarning("업데이트할 아이템 데이터가 null입니다.", "InventoryManager");
                return;
            }
            _currentItemData = itemData;
            if (_itemDataCache.ContainsKey(itemData.itemCode))
            {
                _itemDataCache[itemData.itemCode] = itemData;
            }
            else
            {
                _itemDataCache.Add(itemData.itemCode, itemData);
            }
        }

        #endregion

        #region 데이터 저장 및 로드

        /// <summary>
        /// 인벤토리 데이터를 암호화하여 로컬에 저장합니다.
        /// </summary>
        public void SaveInventoryData()
        {
            if (scritpableobjInventoryData == null)
            {
                LogManager.LogWarning("저장할 인벤토리 데이터가 null입니다.", "InventoryManager");
                return;
            }
            try
            {
                if (_encryption == null)
                    _encryption = new HybridEncryption();
                string jsonData = JsonUtility.ToJson(scritpableobjInventoryData, true);
                string rsaPublicKey = PlayerDataManagerDontdesytoy.Instance.RsaPublicKey;
                if (string.IsNullOrEmpty(rsaPublicKey))
                {
                    LogManager.LogError("RSA 공개키를 찾을 수 없습니다. 암호화 없이 저장합니다.", "InventoryManager");
                    File.WriteAllText(_localSavePath.Replace(".encrypted", ".json"), jsonData);
                    return;
                }
                EncryptedPacket encryptedPacket = _encryption.Encrypt(jsonData, rsaPublicKey);
                SerializableEncryptedPacket serializablePacket = new SerializableEncryptedPacket
                {
                    EncryptedSessionKeyBase64 = Convert.ToBase64String(encryptedPacket.EncryptedSessionKey),
                    EncryptedDataBase64 = Convert.ToBase64String(encryptedPacket.EncryptedData)
                };
                string packetJson = JsonUtility.ToJson(serializablePacket);
                File.WriteAllText(_localSavePath, packetJson);
                LogManager.Log($"인벤토리 데이터를 암호화하여 {_localSavePath}에 저장했습니다.", "InventoryManager");
            }
            catch (Exception e)
            {
                LogManager.LogError($"인벤토리 데이터 암호화 저장 실패: {e.Message}", "InventoryManager");
            }
        }

        /// <summary>
        /// 암호화된 인벤토리 데이터를 로드하고 복호화합니다.
        /// </summary>
        public void LoadEncryptedInventoryData()
        {
            try
            {
                // 암호화 객체가 초기화되지 않았다면 초기화
                if (_encryption == null)
                    _encryption = new HybridEncryption();

                if (File.Exists(_localSavePath))
                {
                    // 암호화된 데이터 로드
                    string packetJson = File.ReadAllText(_localSavePath);
                    SerializableEncryptedPacket serializablePacket =
                        JsonUtility.FromJson<SerializableEncryptedPacket>(packetJson);

                    // Base64 문자열을 바이트 배열로 변환
                    EncryptedPacket encryptedPacket = new EncryptedPacket
                    {
                        EncryptedSessionKey = Convert.FromBase64String(serializablePacket.EncryptedSessionKeyBase64),
                        EncryptedData = Convert.FromBase64String(serializablePacket.EncryptedDataBase64)
                    };

                    // 복호화에 사용할 개인키 확인
                    string rsaPrivateKey = PlayerDataManagerDontdesytoy.Instance.RsaPrivateKey;
                    if (string.IsNullOrEmpty(rsaPrivateKey))
                    {
                        LogManager.LogError("RSA 개인키를 찾을 수 없습니다. 데이터를 복호화할 수 없습니다.", "InventoryManager");
                        return;
                    }

                    // 데이터 복호화
                    string decryptedJson = _encryption.Decrypt(encryptedPacket, rsaPrivateKey);

                    // 복호화된 JSON을 Inventory_Data 객체로 변환
                    JsonUtility.FromJsonOverwrite(decryptedJson, scritpableobjInventoryData);

                    LogManager.Log("암호화된 인벤토리 데이터를 성공적으로 로드했습니다.", "InventoryManager");
                    LogManager.Log($"packetJson: {packetJson}", "InventoryManager");
                    LogManager.Log($"serializablePacket: {JsonUtility.ToJson(serializablePacket)}", "InventoryManager");
                    LogManager.Log($"encryptedPacket.EncryptedSessionKey: {serializablePacket.EncryptedSessionKeyBase64}", "InventoryManager");
                    LogManager.Log($"encryptedPacket.EncryptedData: {serializablePacket.EncryptedDataBase64}", "InventoryManager");
                    LogManager.Log($"decryptedJson: {decryptedJson}", "InventoryManager");
                }
                else
                {
                    LogManager.Log("저장된 암호화 인벤토리 데이터 파일이 없습니다.", "InventoryManager");
                }
            }
            catch (Exception e)
            {
                LogManager.LogError($"인벤토리 데이터 복호화 중 오류 발생: {e.Message}", "InventoryManager");
            }
        }

        #endregion

        #region 서버 데이터 처리

        /// <summary>
        /// 서버에서 인벤토리 데이터를 가져옵니다.
        /// </summary>
        public void LoadDataFromServer()
        {
            ServerManager.Instance.DownloadData("Inventory_Data", (bro) =>
            {
                OnServerDataReceived(bro);
            });
        }

        private void OnServerDataReceived(BackendReturnObject bro)
        {
            if (!bro.IsSuccess())
            {
                LogManager.LogError($"인벤토리 데이터 조회 실패: {bro}", "InventoryManager");
                if (bro.GetStatusCode() == "404")
                {
                    LogManager.Log("서버에 인벤토리 데이터가 없어 새로 생성합니다.", "InventoryManager");
                    CreateDefaultInventory();
                }
                else
                {
                    // 서버 조회 실패 시 로컬 데이터 로드 시도
                    LoadEncryptedInventoryData();
                }
                return;
            }

            var gameDataJson = bro.FlattenRows();
            if (gameDataJson.Count <= 0)
            {
                LogManager.LogWarning("서버에 인벤토리 데이터가 없습니다. 새로 생성합니다.", "InventoryManager");
                CreateDefaultInventory();
                return;
            }

            try
            {
                string inventoryJsonString = gameDataJson[0]["Inventory"].ToString();
                Inventory_Data serverData = JsonConvert.DeserializeObject<Inventory_Data>(inventoryJsonString);

                if (serverData != null)
                {
                    Update_Inventory_Data(serverData);
                    SaveInventoryData(); // 로컬에도 저장
                    LogManager.Log("서버로부터 인벤토리 데이터를 성공적으로 로드하고 업데이트했습니다.", "InventoryManager");
                }
                else
                {
                    LogManager.LogWarning("서버 인벤토리 데이터 파싱에 실패했습니다. 새 인벤토리를 생성합니다.", "InventoryManager");
                    CreateDefaultInventory();
                }
            }
            catch (Exception ex)
            {
                LogManager.LogError($"서버 인벤토리 데이터 처리 중 오류 발생: {ex.Message}", "InventoryManager");
                // 오류 발생 시 로컬 데이터 로드 또는 새 데이터 생성
                LoadEncryptedInventoryData();
            }
        }

        /// <summary>
        /// 현재 인벤토리 데이터를 서버에 업로드합니다.
        /// </summary>
        public void UploadDataToServer()
        {
            if (scritpableobjInventoryData == null) return;

            inventorydataString = JsonConvert.SerializeObject(scritpableobjInventoryData, Formatting.Indented);

            Param param = new Param();
            param.Add("Inventory", inventorydataString);

            ServerManager.Instance.UploadData("Inventory_Data", param, (bro) =>
            {
                if (bro.IsSuccess())
                {
                    LogManager.Log("인벤토리 데이터를 서버에 성공적으로 업로드했습니다.", "InventoryManager");
                }
                else
                {
                    LogManager.LogError($"인벤토리 데이터 업로드 실패: {bro}", "InventoryManager");
                }
            });
        }

        #endregion

        #region 유틸리티 메서드

        /// <summary>
        /// 인벤토리 데이터를 JSON 파일로 내보냅니다. (디버깅용)
        /// </summary>
        public void ExportInventoryDataToJson()
        {
            if (scritpableobjInventoryData == null)
                return;

            try
            {
                string savePath = Path.Combine(Application.persistentDataPath, "inventory_debug_export.json");
                string jsonData = JsonConvert.SerializeObject(scritpableobjInventoryData, Formatting.Indented);
                File.WriteAllText(savePath, jsonData);
                LogManager.Log($"인벤토리 데이터를 {savePath}에 내보냈습니다.", "InventoryManager");
            }
            catch (Exception e)
            {
                LogManager.LogError($"인벤토리 데이터 내보내기 실패: {e.Message}", "InventoryManager");
            }
        }

        /// <summary>
        /// 객체가 null인지 확인합니다.
        /// </summary>
        private static bool IsNullOrEmpty(UnityEngine.Object value)
        {
            return ReferenceEquals(value, null);
        }

        #endregion

        #region 헬퍼 클래스

        [System.Serializable]
        private class JsonItemData
        {
            public string itemName;
            public int itemCode;
            public string itemtype;
            public int itemCount;
            public string itemcoinType;
            public int itemcoinCount;
        }

        #endregion
    }
}

using System.Collections.Generic;
using System.IO;
using BackEnd;
using BackEnd.BackndNewtonsoft.Json;
using UnityEngine;
using System;
using System.Linq;

namespace DogGuns_Games.Lobby
{
    /// <summary>
    /// 인벤토리 데이터를 관리하고 암호화하여 저장/로드하는 매니저 클래스
    /// DontDestroyOnLoad로 씬 전환 시에도 유지됩니다.
    /// </summary>
    public class InventoryDataManagerDontdestory : MonoBehaviour
    {
        #region 필드 및 변수

        [SerializeField] private TextAsset itemDataJsonFile;
        public Inventory_Data scritpableobjInventoryData;
        public string inventorydataString;

        private HybridEncryption _encryption;
        private string _localSavePath;

        // 캐시 필드
        private Dictionary<int, Item_Data> _itemDataCache = new Dictionary<int, Item_Data>();
        // private Item_Data _currentItemData; // 사용되지 않으므로 제거
        private bool _isDataLoaded;

        #endregion

        #region 싱글톤 패턴

        private static InventoryDataManagerDontdestory instance;
        private static readonly object LockObject = new object();

        public static InventoryDataManagerDontdestory Instance
        {
            get
            {
                if (instance == null)
                {
                    lock (LockObject) // 스레드 안전성 보장
                    {
                        if (instance == null)
                        {
                            instance = FindAnyObjectByType<InventoryDataManagerDontdestory>();
                            if (instance == null)
                            {
                                var container = new GameObject("InventoryDataManager");
                                instance = container.AddComponent<InventoryDataManagerDontdestory>();
                                DontDestroyOnLoad(container);
                                LogManager.Log("인벤토리 데이터 매니저 인스턴스가 생성되었습니다.", LogManager.LogCategory.InventoryManager);
                            }
                        }
                    }
                }

                return instance;
            }
        }

        #endregion

        #region Unity 라이프사이클

        private void Awake()
        {
            // 싱글톤 패턴 구현
            if (Instance != this)
            {
                Destroy(gameObject);
                return;
            }

            DontDestroyOnLoad(gameObject);

            // 초기화
            _encryption = new HybridEncryption();
            _localSavePath = Path.Combine(Application.persistentDataPath, "inventoryData.encrypted");

            // Inventory_Data 초기화
            if (scritpableobjInventoryData == null)
                scritpableobjInventoryData = ScriptableObject.CreateInstance<Inventory_Data>();
        }

        private void Start()
        {
            LoadItemDataFromJson();

            if (!_isDataLoaded)
            {
                LogManager.LogWarning("JSON에서 아이템 데이터를 불러오지 못했습니다.", LogManager.LogCategory.InventoryManager);
            }

            // 서버에서 인벤토리 데이터 로드
            LoadDataFromServer();
        }

        #endregion

        #region 초기화 및 데이터 로드

        /// <summary>
        /// 기본 인벤토리 데이터를 생성합니다.
        /// </summary>
        private void CreateDefaultInventory()
        {
            try
            {
                LogManager.Log("새 인벤토리 데이터를 생성합니다.", LogManager.LogCategory.InventoryManager);

                // 인벤토리 데이터가 이미 초기화되어 있는지 확인
                if (scritpableobjInventoryData == null)
                {
                    scritpableobjInventoryData = ScriptableObject.CreateInstance<Inventory_Data>();
                }
                else
                {
                    scritpableobjInventoryData.InitInventory();
                }

                // 기본 아이템 추가 (필요한 경우)
                // 예: 시작용 기본 장비 추가
                if (_isDataLoaded && _itemDataCache.Count > 0)
                {
                    // 아이템 목록에서 첫 번째 아이템을 기본 아이템으로 추가 (예시)
                    var defaultItemCode = _itemDataCache.Keys.First();
                    var defaultItem = _itemDataCache[defaultItemCode];

                    scritpableobjInventoryData.AddItem(defaultItem);
                    LogManager.Log($"기본 아이템 추가: {defaultItem.itemName} (코드: {defaultItem.itemCode})", LogManager.LogCategory.InventoryManager);
                }

                // 인벤토리 JSON 문자열 생성
                inventorydataString = JsonConvert.SerializeObject(scritpableobjInventoryData, Formatting.Indented);

                // 로컬에 저장
                SaveInventoryData();

                // 서버에 저장
                UploadDataToServer();
            }
            catch (Exception ex)
            {
                LogManager.LogError($"기본 인벤토리 생성 중 오류 발생: {ex.Message}", LogManager.LogCategory.InventoryManager);
            }
        }

        /// <summary>
        /// JSON 파일에서 아이템 데이터를 로드합니다.
        /// </summary>
        private void LoadItemDataFromJson()
        {
            if (itemDataJsonFile == null)
            {
                LogManager.LogError("아이템 데이터 JSON 파일이 인스펙터에서 할당되지 않았습니다.", LogManager.LogCategory.InventoryManager);
                return;
            }

            try
            {
                JsonItemData[] jsonItems = JsonConvert.DeserializeObject<JsonItemData[]>(itemDataJsonFile.text);

                if (jsonItems == null || jsonItems.Length == 0)
                {
                    LogManager.LogWarning("JSON 데이터에서 아이템을 찾을 수 없습니다.", LogManager.LogCategory.InventoryManager);
                    return;
                }

                _itemDataCache.Clear();

                foreach (var jsonItem in jsonItems)
                {
                    Item_Data itemData = ScriptableObject.CreateInstance<Item_Data>();
                    itemData.itemName = jsonItem.itemName;
                    itemData.itemCode = jsonItem.itemCode;
                    itemData.itemtype = jsonItem.itemtype;
                    itemData.itemCount = jsonItem.itemCount;
                    itemData.itemcoinType = jsonItem.itemcoinType;
                    itemData.itemcoinCount = jsonItem.itemcoinCount;

                    _itemDataCache[itemData.itemCode] = itemData;
                }

                _isDataLoaded = true;
                LogManager.Log($"JSON 데이터에서 {_itemDataCache.Count}개의 아이템을 성공적으로 로드했습니다.", LogManager.LogCategory.InventoryManager);
            }
            catch (Exception e)
            {
                LogManager.LogError($"JSON 데이터 파싱 오류: {e.Message}", LogManager.LogCategory.InventoryManager);
            }
        }

        #endregion

        #region 인벤토리 및 아이템 관리

        /// <summary>
        /// 아이템 코드로 아이템 데이터를 가져옵니다.
        /// </summary>
        /// <param name="itemCode">찾을 아이템의 코드</param>
        /// <returns>아이템 데이터 또는 null</returns>
        public Item_Data GetItemByItemCode(int itemCode)
        {
            if (!_isDataLoaded)
            {
                LogManager.LogWarning("아이템 데이터가 아직 로드되지 않았습니다.", LogManager.LogCategory.InventoryManager);
                return null;
            }

            if (_itemDataCache.TryGetValue(itemCode, out Item_Data item))
            {
                // _currentItemData = item; // 사용하지 않으므로 제거
                return item;
            }

            LogManager.LogWarning($"코드 {itemCode}를 가진 아이템을 찾을 수 없습니다.", LogManager.LogCategory.InventoryManager);
            return null;
        }

        /// <summary>
        /// 인벤토리 데이터를 업데이트합니다.
        /// </summary>
        /// <param name="inventoryData">새로운 인벤토리 데이터</param>
        public void Update_Inventory_Data(Inventory_Data inventoryData)
        {
            if (inventoryData == null)
            {
                LogManager.LogWarning("업데이트할 인벤토리 데이터가 null입니다.", LogManager.LogCategory.InventoryManager);
                return;
            }
            scritpableobjInventoryData = inventoryData;
            try
            {
                inventorydataString = JsonConvert.SerializeObject(scritpableobjInventoryData, Formatting.Indented);
#if UNITY_EDITOR
                LogManager.Log("<color=green>인벤토리 데이터 업데이트 완료</color>", LogManager.LogCategory.InventoryManager);
                LogManager.Log($"인벤토리 데이터: {inventorydataString}", LogManager.LogCategory.InventoryManager);
#endif
            }
            catch (Exception ex)
            {
                LogManager.LogError($"인벤토리 데이터 직렬화 중 오류: {ex.Message}", LogManager.LogCategory.InventoryManager);
            }
            SaveInventoryData();
        }

        /// <summary>
        /// 현재 선택된 아이템 데이터를 업데이트합니다.
        /// </summary>
        /// <param name="itemData">업데이트할 아이템 데이터</param>
        public void UpdateItemData(Item_Data itemData)
        {
            if (itemData == null)
            {
                LogManager.LogWarning("업데이트할 아이템 데이터가 null입니다.", LogManager.LogCategory.InventoryManager);
                return;
            }
            // _currentItemData = itemData; // 사용하지 않으므로 제거
            _itemDataCache[itemData.itemCode] = itemData;
        }

        #endregion

        #region 데이터 저장 및 로드

        /// <summary>
        /// 인벤토리 데이터를 암호화하여 로컬에 저장합니다.
        /// </summary>
        public void SaveInventoryData()
        {
            if (scritpableobjInventoryData == null)
            {
                LogManager.LogWarning("저장할 인벤토리 데이터가 null입니다.", LogManager.LogCategory.InventoryManager);
                return;
            }
            try
            {
                if (_encryption == null)
                    _encryption = new HybridEncryption();
                string jsonData = JsonUtility.ToJson(scritpableobjInventoryData, true);
                string rsaPublicKey = PlayerDataManagerDontdesytoy.Instance.RsaPublicKey;
                if (string.IsNullOrEmpty(rsaPublicKey))
                {
                    LogManager.LogError("RSA 공개키를 찾을 수 없습니다. 암호화 없이 저장합니다.", LogManager.LogCategory.InventoryManager);
                    File.WriteAllText(_localSavePath.Replace(".encrypted", ".json"), jsonData);
                    return;
                }
                EncryptedPacket encryptedPacket = _encryption.Encrypt(jsonData, rsaPublicKey);
                SerializableEncryptedPacket serializablePacket = new SerializableEncryptedPacket
                {
                    EncryptedSessionKeyBase64 = Convert.ToBase64String(encryptedPacket.EncryptedSessionKey),
                    EncryptedDataBase64 = Convert.ToBase64String(encryptedPacket.EncryptedData)
                };
                string packetJson = JsonUtility.ToJson(serializablePacket);
                File.WriteAllText(_localSavePath, packetJson);
                LogManager.Log($"인벤토리 데이터를 암호화하여 {_localSavePath}에 저장했습니다.", LogManager.LogCategory.InventoryManager);
            }
            catch (Exception e)
            {
                LogManager.LogError($"인벤토리 데이터 암호화 저장 실패: {e.Message}", LogManager.LogCategory.InventoryManager);
            }
        }

        /// <summary>
        /// 암호화된 인벤토리 데이터를 로드하고 복호화합니다.
        /// </summary>
        public void LoadEncryptedInventoryData()
        {
            try
            {
                // 암호화 객체가 초기화되지 않았다면 초기화
                if (_encryption == null)
                    _encryption = new HybridEncryption();

                if (File.Exists(_localSavePath))
                {
                    // 암호화된 데이터 로드
                    string packetJson = File.ReadAllText(_localSavePath);
                    SerializableEncryptedPacket serializablePacket =
                        JsonUtility.FromJson<SerializableEncryptedPacket>(packetJson);

                    // Base64 문자열을 바이트 배열로 변환
                    EncryptedPacket encryptedPacket = new EncryptedPacket
                    {
                        EncryptedSessionKey = Convert.FromBase64String(serializablePacket.EncryptedSessionKeyBase64),
                        EncryptedData = Convert.FromBase64String(serializablePacket.EncryptedDataBase64)
                    };

                    // 복호화에 사용할 개인키 확인
                    string rsaPrivateKey = PlayerDataManagerDontdesytoy.Instance.RsaPrivateKey;
                    if (string.IsNullOrEmpty(rsaPrivateKey))
                    {
                        LogManager.LogError("RSA 개인키를 찾을 수 없습니다. 데이터를 복호화할 수 없습니다.", LogManager.LogCategory.InventoryManager);
                        return;
                    }

                    // 데이터 복호화
                    string decryptedJson = _encryption.Decrypt(encryptedPacket, rsaPrivateKey);

                    // 복호화된 JSON을 Inventory_Data 객체로 변환
                    JsonUtility.FromJsonOverwrite(decryptedJson, scritpableobjInventoryData);

                    LogManager.Log("암호화된 인벤토리 데이터를 성공적으로 로드했습니다.", LogManager.LogCategory.InventoryManager);
                    LogManager.Log($"packetJson: {packetJson}", LogManager.LogCategory.InventoryManager);
                    LogManager.Log($"serializablePacket: {JsonUtility.ToJson(serializablePacket)}", LogManager.LogCategory.InventoryManager);
                    LogManager.Log($"encryptedPacket.EncryptedSessionKey: {serializablePacket.EncryptedSessionKeyBase64}", LogManager.LogCategory.InventoryManager);
                    LogManager.Log($"encryptedPacket.EncryptedData: {serializablePacket.EncryptedDataBase64}", LogManager.LogCategory.InventoryManager);
                    LogManager.Log($"decryptedJson: {decryptedJson}", LogManager.LogCategory.InventoryManager);
                }
                else
                {
                    LogManager.Log("저장된 암호화 인벤토리 데이터 파일이 없습니다.", LogManager.LogCategory.InventoryManager);
                }
            }
            catch (Exception e)
            {
                LogManager.LogError($"인벤토리 데이터 복호화 중 오류 발생: {e.Message}", LogManager.LogCategory.InventoryManager);
            }
        }

        #endregion

        #region 서버 데이터 처리

        /// <summary>
        /// 서버에서 인벤토리 데이터를 가져옵니다.
        /// </summary>
        public void LoadDataFromServer()
        {
            ServerManager.Instance.DownloadData("Inventory_Data", (bro) =>
            {
                OnServerDataReceived(bro);
            });
        }

        private void OnServerDataReceived(BackendReturnObject bro)
        {
            if (!bro.IsSuccess())
            {
                LogManager.LogError($"인벤토리 데이터 조회 실패: {bro}", LogManager.LogCategory.InventoryManager);
                if (bro.GetStatusCode() == "404")
                {
                    LogManager.Log("서버에 인벤토리 데이터가 없어 새로 생성합니다.", LogManager.LogCategory.InventoryManager);
                    CreateDefaultInventory();
                }
                else
                {
                    // 서버 조회 실패 시 로컬 데이터 로드 시도
                    LoadEncryptedInventoryData();
                }
                return;
            }

            var gameDataJson = bro.FlattenRows();
            if (gameDataJson.Count <= 0)
            {
                LogManager.LogWarning("서버에 인벤토리 데이터가 없습니다. 새로 생성합니다.", LogManager.LogCategory.InventoryManager);
                CreateDefaultInventory();
                return;
            }

            try
            {
                string inventoryJsonString = gameDataJson[0]["Inventory"].ToString();
                Inventory_Data serverData = JsonConvert.DeserializeObject<Inventory_Data>(inventoryJsonString);

                if (serverData != null)
                {
                    Update_Inventory_Data(serverData);
                    SaveInventoryData(); // 로컬에도 저장
                    LogManager.Log("서버로부터 인벤토리 데이터를 성공적으로 로드하고 업데이트했습니다.", LogManager.LogCategory.InventoryManager);
                }
                else
                {
                    LogManager.LogWarning("서버 인벤토리 데이터 파싱에 실패했습니다. 새 인벤토리를 생성합니다.", LogManager.LogCategory.InventoryManager);
                    CreateDefaultInventory();
                }
            }
            catch (Exception ex)
            {
                LogManager.LogError($"서버 인벤토리 데이터 처리 중 오류 발생: {ex.Message}", LogManager.LogCategory.InventoryManager);
                // 오류 발생 시 로컬 데이터 로드 또는 새 데이터 생성
                LoadEncryptedInventoryData();
            }
        }

        /// <summary>
        /// 현재 인벤토리 데이터를 서버에 업로드합니다.
        /// </summary>
        public void UploadDataToServer()
        {
            if (scritpableobjInventoryData == null) return;

            inventorydataString = JsonConvert.SerializeObject(scritpableobjInventoryData, Formatting.Indented);

            Param param = new Param();
            param.Add("Inventory", inventorydataString);

            ServerManager.Instance.UploadData("Inventory_Data", param, (bro) =>
            {
                if (bro.IsSuccess())
                {
                    LogManager.Log("인벤토리 데이터를 서버에 성공적으로 업로드했습니다.", LogManager.LogCategory.InventoryManager);
                }
                else
                {
                    LogManager.LogError($"인벤토리 데이터 업로드 실패: {bro}", LogManager.LogCategory.InventoryManager);
                }
            });
        }

        #endregion

        #region 유틸리티 메서드

        /// <summary>
        /// 인벤토리 데이터를 JSON 파일로 내보냅니다. (디버깅용)
        /// </summary>
        public void ExportInventoryDataToJson()
        {
            if (scritpableobjInventoryData == null)
                return;

            try
            {
                string savePath = Path.Combine(Application.persistentDataPath, "inventory_debug_export.json");
                string jsonData = JsonConvert.SerializeObject(scritpableobjInventoryData, Formatting.Indented);
                File.WriteAllText(savePath, jsonData);
                LogManager.Log($"인벤토리 데이터를 {savePath}에 내보냈습니다.", LogManager.LogCategory.InventoryManager);
            }
            catch (Exception e)
            {
                LogManager.LogError($"인벤토리 데이터 내보내기 실패: {e.Message}", LogManager.LogCategory.InventoryManager);
            }
        }

        /// <summary>
        /// 객체가 null인지 확인합니다.
        /// </summary>
        private static bool IsNullOrEmpty(UnityEngine.Object value)
        {
            return ReferenceEquals(value, null);
        }

        #endregion

        #region 헬퍼 클래스

        [System.Serializable]
        private class JsonItemData
        {
            public string itemName;
            public int itemCode;
            public string itemtype;
            public int itemCount;
            public string itemcoinType;
            public int itemcoinCount;
        }

        #endregion
    }
}

using System;
using System.IO;
using BackEnd;
using UnityEngine;

namespace DogGuns_Games
{
    /// <summary>
    /// 플레이어 데이터를 관리하고 암호화하여 저장/로드하는 매니저 클래스
    /// DontDestroyOnLoad로 씬 전환 시에도 유지됩니다.
    /// </summary>
    public class PlayerDataManagerDontdesytoy : MonoBehaviour
    {
        #region 변수, 프로퍼티, 필드

        public PlayerData scritpableobjPlayerData;

        public string RsaPublicKey => _rsaPublicKey;
        public string RsaPrivateKey => _rsaPrivateKey;

        private string _rsaPublicKey;
        private string _rsaPrivateKey;
        private HybridEncryption _encryption;

        // 플레이어 데이터 속성에 대한 접근자
        public int SelectWeaponIndex
        {
            get => scritpableobjPlayerData.selelcWeaponIndex;
            set => scritpableobjPlayerData.selelcWeaponIndex = value;
        }

        public int SelectCharacterIndex
        {
            get => scritpableobjPlayerData.selectCharacterIndex;
            set => scritpableobjPlayerData.selectCharacterIndex = value;
        }

        #endregion

        #region 싱글톤 및 초기화

        private static PlayerDataManagerDontdesytoy instance;
        private static readonly object LockObject = new object();

        public static PlayerDataManagerDontdesytoy Instance
        {
            get
            {
                if (instance == null)
                {
                    lock (LockObject)
                    {
                        if (instance == null)
                        {
                            instance = FindAnyObjectByType<PlayerDataManagerDontdesytoy>();
                            if (instance == null)
                            {
                                var container = new GameObject("PlayerDataManager");
                                instance = container.AddComponent<PlayerDataManagerDontdesytoy>();
                                DontDestroyOnLoad(container);
                            }
                        }
                    }
                }
                return instance;
            }
        }

        private void Awake()
        {
            // 싱글톤 패턴 구현
            if (Instance != this)
            {
                Destroy(gameObject);
                return;
            }

            DontDestroyOnLoad(gameObject);

            // PlayerData 초기화
            if (scritpableobjPlayerData == null)
                scritpableobjPlayerData = ScriptableObject.CreateInstance<PlayerData>();

            // 암호화 객체 초기화
            _encryption = new HybridEncryption();

            // 키 생성 또는 로드
            GenerateOrLoadRsaKeys();
        }

        #endregion

        #region 로컬 데이터 관리

        /// <summary>
        /// RSA 키 쌍을 생성하거나 기존 키를 로드합니다.
        /// </summary>
        private void GenerateOrLoadRsaKeys()
        {
            try
            {
                var keyPath = Path.Combine(Application.persistentDataPath, "rsakeys.json");
                if (File.Exists(keyPath))
                {
                    string keyJson = File.ReadAllText(keyPath);
                    var keyContainer = JsonUtility.FromJson<KeyContainer>(keyJson);
                    _rsaPublicKey = keyContainer.publicKey;
                    _rsaPrivateKey = keyContainer.privateKey;
                    LogManager.Log("로컬 파일에서 RSA 키 쌍을 로드했습니다.", LogManager.LogCategory.PlayerManager);
                }
                else
                {
                    _encryption.GenerateRsaKeys(out _rsaPublicKey, out _rsaPrivateKey);
                    var keyContainer = new KeyContainer { publicKey = _rsaPublicKey, privateKey = _rsaPrivateKey };
                    string keyJson = JsonUtility.ToJson(keyContainer);
                    File.WriteAllText(keyPath, keyJson);
                    LogManager.Log("새로운 RSA 키 쌍을 생성하고 로컬 파일에 저장했습니다.", LogManager.LogCategory.PlayerManager);
                }
            }
            catch (Exception ex)
            {
                LogManager.LogError($"RSA 키 관리 중 오류 발생: {ex.Message}", LogManager.LogCategory.PlayerManager);
                _encryption.GenerateRsaKeys(out _rsaPublicKey, out _rsaPrivateKey);
                LogManager.Log("RSA 키 오류로 인해 새로운 키 쌍을 생성했습니다.", LogManager.LogCategory.PlayerManager);
            }
        }

        /// <summary>
        /// 플레이어 데이터를 암호화하여 로컬에 저장합니다.
        /// </summary>
        public void SavePlayerData()
        {
            try
            {
                var savePath = Path.Combine(Application.persistentDataPath, "playerData.encrypted");
                if (scritpableobjPlayerData == null)
                {
                    LogManager.LogWarning("저장할 플레이어 데이터가 null입니다.");
                    return;
                }
                var jsonData = JsonUtility.ToJson(scritpableobjPlayerData, true);
                EncryptedPacket encryptedPacket = _encryption.Encrypt(jsonData, _rsaPublicKey);
                SerializableEncryptedPacket serializablePacket = new SerializableEncryptedPacket
                {
                    EncryptedSessionKeyBase64 = Convert.ToBase64String(encryptedPacket.EncryptedSessionKey),
                    EncryptedDataBase64 = Convert.ToBase64String(encryptedPacket.EncryptedData)
                };
                string packetJson = JsonUtility.ToJson(serializablePacket);
                File.WriteAllText(savePath, packetJson);
                LogManager.Log($"플레이어 데이터가 암호화되어 {savePath}에 저장되었습니다.");
            }
            catch (Exception ex)
            {
                LogManager.LogError($"플레이어 데이터 저장 중 오류 발생: {ex.Message}");
            }
        }

        /// <summary>
        /// 로컬에서 암호화된 플레이어 데이터를 로드하고 복호화합니다.
        /// </summary>
        public void LoadPlayerData()
        {
            try
            {
                var savePath = Path.Combine(Application.persistentDataPath, "playerData.encrypted");
                if (File.Exists(savePath))
                {
                    string packetJson = File.ReadAllText(savePath);
                    SerializableEncryptedPacket serializablePacket = JsonUtility.FromJson<SerializableEncryptedPacket>(packetJson);
                    EncryptedPacket encryptedPacket = new EncryptedPacket
                    {
                        EncryptedSessionKey = Convert.FromBase64String(serializablePacket.EncryptedSessionKeyBase64),
                        EncryptedData = Convert.FromBase64String(serializablePacket.EncryptedDataBase64)
                    };
                    string decryptedJson = _encryption.Decrypt(encryptedPacket, _rsaPrivateKey);
                    JsonUtility.FromJsonOverwrite(decryptedJson, scritpableobjPlayerData);
                    LogManager.Log("로컬에서 플레이어 데이터를 성공적으로 로드했습니다.");
                }
                else
                {
                    LogManager.LogWarning("저장된 플레이어 데이터 파일이 없습니다. 새 데이터를 생성합니다.");
                }
            }
            catch (Exception ex)
            {
                LogManager.LogError($"플레이어 데이터 로드 중 오류 발생: {ex.Message}");
            }
        }

        /// <summary>
        /// 플레이어 데이터를 업데이트합니다.
        /// </summary>
        /// <param name="playerData">새로운 플레이어 데이터</param>
        public void UpdatePlayerData(PlayerData playerData)
        {
            scritpableobjPlayerData = playerData;
            LogManager.Log("플레이어 데이터가 업데이트되었습니다.");
        }

        #endregion

        #region 서버 데이터 처리

        /// <summary>
        /// 서버에서 플레이어 데이터를 가져옵니다.
        /// </summary>
        /// <param name="onDataNotExist">서버에 데이터가 없을 때 실행할 콜백</param>
        public void LoadDataFromServer(Action onDataNotExist)
        {
            ServerManager.Instance.DownloadData("User_Data", (bro) =>
            {
                OnServerDataReceived(bro, onDataNotExist);
            });
        }

        private void OnServerDataReceived(BackendReturnObject bro, Action onDataNotExist)
        {
            if (!bro.IsSuccess())
            {
                LogManager.LogError($"게임 정보 조회에 실패했습니다. : {bro}");
                if (bro.GetStatusCode() == "404")
                {
                    onDataNotExist?.Invoke();
                }
                return;
            }
            var gameDataJson = bro.FlattenRows();
            if (gameDataJson.Count <= 0)
            {
                LogManager.LogWarning("서버에 데이터가 존재하지 않습니다.");
                onDataNotExist?.Invoke();
                return;
            }
            LogManager.Log("서버에서 게임 정보를 성공적으로 조회했습니다.");
            var serverDataJson = gameDataJson[0];

            // 서버 데이터 파싱
            PlayerData serverData = ScriptableObject.CreateInstance<PlayerData>();
            serverData.level = int.Parse(serverDataJson["level"].ToString());
            serverData.currency1 = int.Parse(serverDataJson["Money1"].ToString());
            serverData.currency2 = int.Parse(serverDataJson["Money2"].ToString());
            serverData.experience = float.Parse(serverDataJson["experience"].ToString());
            serverData.UID = serverDataJson["uid"].ToString();
            serverData.nickname = serverDataJson["nickname"].ToString();

            // 로컬 데이터 로드
            LoadPlayerData();
            PlayerData localData = scritpableobjPlayerData;

            // 데이터 비교 및 최종 데이터 결정
            PlayerData finalData = ResolveDataConflict(serverData, localData);

            UpdatePlayerData(finalData);
            SavePlayerData(); // 최종 데이터를 로컬에 저장

            // 필요한 경우 서버 데이터 업데이트
            if (finalData == localData)
            {
                UploadDataToServer();
            }
        }

        private PlayerData ResolveDataConflict(PlayerData serverData, PlayerData localData)
        {
            if (localData.level > serverData.level || 
                (localData.level == serverData.level && localData.experience > serverData.experience))
            {
                LogManager.Log("로컬 데이터가 더 최신이므로 사용합니다.");
                return localData;
            }
            LogManager.Log("서버 데이터가 더 최신이므로 사용합니다.");
            return serverData;
        }

        /// <summary>
        /// 현재 플레이어 데이터를 서버에 업로드(Insert or Update)합니다.
        /// </summary>
        public void UploadDataToServer()
        {
            Param param = new Param();
            param.Add("nickname", scritpableobjPlayerData.nickname);
            param.Add("uid", scritpableobjPlayerData.UID);
            param.Add("Money1", scritpableobjPlayerData.currency1);
            param.Add("Money2", scritpableobjPlayerData.currency2);
            param.Add("experience", scritpableobjPlayerData.experience);
            param.Add("level", scritpableobjPlayerData.level);

            ServerManager.Instance.UploadData("User_Data", param, (bro) =>
            {
                if (bro.IsSuccess())
                {
                    LogManager.Log("플레이어 데이터를 서버에 성공적으로 업로드했습니다.");
                }
                else
                {
                    LogManager.LogError($"플레이어 데이터 업로드 실패: {bro}");
                }
            });
        }

        #endregion

        #region 유틸리티


        /// <summary>
        /// RSA 키 저장을 위한 헬퍼 클래스
        /// </summary>
        [System.Serializable]
        private class KeyContainer
        {
            public string publicKey;
            public string privateKey;
        }

        #endregion
    }
}

using System;
using System.IO;
using BackEnd;
using UnityEngine;

namespace DogGuns_Games
{
    /// <summary>
    /// 플레이어 데이터를 관리하고 암호화하여 저장/로드하는 매니저 클래스
    /// DontDestroyOnLoad로 씬 전환 시에도 유지됩니다.
    /// </summary>
    public class PlayerDataManagerDontdesytoy : MonoBehaviour
    {
        #region 변수, 프로퍼티, 필드

        public PlayerData scritpableobjPlayerData;

        public string RsaPublicKey => _rsaPublicKey;
        public string RsaPrivateKey => _rsaPrivateKey;

        private string _rsaPublicKey;
        private string _rsaPrivateKey;
        private HybridEncryption _encryption;

        // 플레이어 데이터 속성에 대한 접근자
        public int SelectWeaponIndex
        {
            get => scritpableobjPlayerData.selelcWeaponIndex;
            set => scritpableobjPlayerData.selelcWeaponIndex = value;
        }

        public int SelectCharacterIndex
        {
            get => scritpableobjPlayerData.selectCharacterIndex;
            set => scritpableobjPlayerData.selectCharacterIndex = value;
        }

        #endregion

        #region 싱글톤 및 초기화

        private static PlayerDataManagerDontdesytoy instance;
        private static readonly object LockObject = new object();

        public static PlayerDataManagerDontdesytoy Instance
        {
            get
            {
                if (instance == null)
                {
                    lock (LockObject)
                    {
                        if (instance == null)
                        {
                            instance = FindAnyObjectByType<PlayerDataManagerDontdesytoy>();
                            if (instance == null)
                            {
                                var container = new GameObject("PlayerDataManager");
                                instance = container.AddComponent<PlayerDataManagerDontdesytoy>();
                                DontDestroyOnLoad(container);
                            }
                        }
                    }
                }
                return instance;
            }
        }

        private void Awake()
        {
            // 싱글톤 패턴 구현
            if (Instance != this)
            {
                Destroy(gameObject);
                return;
            }

            DontDestroyOnLoad(gameObject);

            // PlayerData 초기화
            if (scritpableobjPlayerData == null)
                scritpableobjPlayerData = ScriptableObject.CreateInstance<PlayerData>();

            // 암호화 객체 초기화
            _encryption = new HybridEncryption();

            // 키 생성 또는 로드
            GenerateOrLoadRsaKeys();
        }

        #endregion

        #region 로컬 데이터 관리

        /// <summary>
        /// RSA 키 쌍을 생성하거나 기존 키를 로드합니다.
        /// </summary>
        private void GenerateOrLoadRsaKeys()
        {
            try
            {
                var keyPath = Path.Combine(Application.persistentDataPath, "rsakeys.json");
                if (File.Exists(keyPath))
                {
                    string keyJson = File.ReadAllText(keyPath);
                    var keyContainer = JsonUtility.FromJson<KeyContainer>(keyJson);
                    _rsaPublicKey = keyContainer.publicKey;
                    _rsaPrivateKey = keyContainer.privateKey;
                    LogManager.Log("로컬 파일에서 RSA 키 쌍을 로드했습니다.", LogManager.LogCategory.PlayerManager);
                }
                else
                {
                    _encryption.GenerateRsaKeys(out _rsaPublicKey, out _rsaPrivateKey);
                    var keyContainer = new KeyContainer { publicKey = _rsaPublicKey, privateKey = _rsaPrivateKey };
                    string keyJson = JsonUtility.ToJson(keyContainer);
                    File.WriteAllText(keyPath, keyJson);
                    LogManager.Log("새로운 RSA 키 쌍을 생성하고 로컬 파일에 저장했습니다.", LogManager.LogCategory.PlayerManager);
                }
            }
            catch (Exception ex)
            {
                LogManager.LogError($"RSA 키 관리 중 오류 발생: {ex.Message}", LogManager.LogCategory.PlayerManager);
                _encryption.GenerateRsaKeys(out _rsaPublicKey, out _rsaPrivateKey);
                LogManager.Log("RSA 키 오류로 인해 새로운 키 쌍을 생성했습니다.", LogManager.LogCategory.PlayerManager);
            }
        }

        /// <summary>
        /// 플레이어 데이터를 암호화하여 로컬에 저장합니다.
        /// </summary>
        public void SavePlayerData()
        {
            try
            {
                var savePath = Path.Combine(Application.persistentDataPath, "playerData.encrypted");
                if (scritpableobjPlayerData == null)
                {
                    LogManager.LogWarning("저장할 플레이어 데이터가 null입니다.");
                    return;
                }
                var jsonData = JsonUtility.ToJson(scritpableobjPlayerData, true);
                EncryptedPacket encryptedPacket = _encryption.Encrypt(jsonData, _rsaPublicKey);
                SerializableEncryptedPacket serializablePacket = new SerializableEncryptedPacket
                {
                    EncryptedSessionKeyBase64 = Convert.ToBase64String(encryptedPacket.EncryptedSessionKey),
                    EncryptedDataBase64 = Convert.ToBase64String(encryptedPacket.EncryptedData)
                };
                string packetJson = JsonUtility.ToJson(serializablePacket);
                File.WriteAllText(savePath, packetJson);
                LogManager.Log($"플레이어 데이터가 암호화되어 {savePath}에 저장되었습니다.");
            }
            catch (Exception ex)
            {
                LogManager.LogError($"플레이어 데이터 저장 중 오류 발생: {ex.Message}");
            }
        }

        /// <summary>
        /// 로컬에서 암호화된 플레이어 데이터를 로드하고 복호화합니다.
        /// </summary>
        public void LoadPlayerData()
        {
            try
            {
                var savePath = Path.Combine(Application.persistentDataPath, "playerData.encrypted");
                if (File.Exists(savePath))
                {
                    string packetJson = File.ReadAllText(savePath);
                    SerializableEncryptedPacket serializablePacket = JsonUtility.FromJson<SerializableEncryptedPacket>(packetJson);
                    EncryptedPacket encryptedPacket = new EncryptedPacket
                    {
                        EncryptedSessionKey = Convert.FromBase64String(serializablePacket.EncryptedSessionKeyBase64),
                        EncryptedData = Convert.FromBase64String(serializablePacket.EncryptedDataBase64)
                    };
                    string decryptedJson = _encryption.Decrypt(encryptedPacket, _rsaPrivateKey);
                    JsonUtility.FromJsonOverwrite(decryptedJson, scritpableobjPlayerData);
                    LogManager.Log("로컬에서 플레이어 데이터를 성공적으로 로드했습니다.");
                }
                else
                {
                    LogManager.LogWarning("저장된 플레이어 데이터 파일이 없습니다. 새 데이터를 생성합니다.");
                }
            }
            catch (Exception ex)
            {
                LogManager.LogError($"플레이어 데이터 로드 중 오류 발생: {ex.Message}");
            }
        }

        /// <summary>
        /// 플레이어 데이터를 업데이트합니다.
        /// </summary>
        /// <param name="playerData">새로운 플레이어 데이터</param>
        public void UpdatePlayerData(PlayerData playerData)
        {
            scritpableobjPlayerData = playerData;
            LogManager.Log("플레이어 데이터가 업데이트되었습니다.");
        }

        #endregion

        #region 서버 데이터 처리

        /// <summary>
        /// 서버에서 플레이어 데이터를 가져옵니다.
        /// </summary>
        /// <param name="onDataNotExist">서버에 데이터가 없을 때 실행할 콜백</param>
        public void LoadDataFromServer(Action onDataNotExist)
        {
            ServerManager.Instance.DownloadData("User_Data", (bro) =>
            {
                OnServerDataReceived(bro, onDataNotExist);
            });
        }

        private void OnServerDataReceived(BackendReturnObject bro, Action onDataNotExist)
        {
            if (!bro.IsSuccess())
            {
                LogManager.LogError($"게임 정보 조회에 실패했습니다. : {bro}");
                if (bro.GetStatusCode() == "404")
                {
                    onDataNotExist?.Invoke();
                }
                return;
            }
            var gameDataJson = bro.FlattenRows();
            if (gameDataJson.Count <= 0)
            {
                LogManager.LogWarning("서버에 데이터가 존재하지 않습니다.");
                onDataNotExist?.Invoke();
                return;
            }
            LogManager.Log("서버에서 게임 정보를 성공적으로 조회했습니다.");
            var serverDataJson = gameDataJson[0];

            // 서버 데이터 파싱
            PlayerData serverData = ScriptableObject.CreateInstance<PlayerData>();
            serverData.level = int.Parse(serverDataJson["level"].ToString());
            serverData.currency1 = int.Parse(serverDataJson["Money1"].ToString());
            serverData.currency2 = int.Parse(serverDataJson["Money2"].ToString());
            serverData.experience = float.Parse(serverDataJson["experience"].ToString());
            serverData.UID = serverDataJson["uid"].ToString();
            serverData.nickname = serverDataJson["nickname"].ToString();

            // 로컬 데이터 로드
            LoadPlayerData();
            PlayerData localData = scritpableobjPlayerData;

            // 데이터 비교 및 최종 데이터 결정
            PlayerData finalData = ResolveDataConflict(serverData, localData);

            UpdatePlayerData(finalData);
            SavePlayerData(); // 최종 데이터를 로컬에 저장

            // 필요한 경우 서버 데이터 업데이트
            if (finalData == localData)
            {
                UploadDataToServer();
            }
        }

        private PlayerData ResolveDataConflict(PlayerData serverData, PlayerData localData)
        {
            if (localData.level > serverData.level || 
                (localData.level == serverData.level && localData.experience > serverData.experience))
            {
                LogManager.Log("로컬 데이터가 더 최신이므로 사용합니다.");
                return localData;
            }
            LogManager.Log("서버 데이터가 더 최신이므로 사용합니다.");
            return serverData;
        }

        /// <summary>
        /// 현재 플레이어 데이터를 서버에 업로드(Insert or Update)합니다.
        /// </summary>
        public void UploadDataToServer()
        {
            Param param = new Param();
            param.Add("nickname", scritpableobjPlayerData.nickname);
            param.Add("uid", scritpableobjPlayerData.UID);
            param.Add("Money1", scritpableobjPlayerData.currency1);
            param.Add("Money2", scritpableobjPlayerData.currency2);
            param.Add("experience", scritpableobjPlayerData.experience);
            param.Add("level", scritpableobjPlayerData.level);

            ServerManager.Instance.UploadData("User_Data", param, (bro) =>
            {
                if (bro.IsSuccess())
                {
                    LogManager.Log("플레이어 데이터를 서버에 성공적으로 업로드했습니다.", LogManager.LogCategory.PlayerManager);
                }
                else
                {
                    LogManager.LogError($"플레이어 데이터 업로드 실패: {bro}", LogManager.LogCategory.PlayerManager);
                }
            });
        }

        #endregion

        #region 유틸리티


        /// <summary>
        /// RSA 키 저장을 위한 헬퍼 클래스
        /// </summary>
        [System.Serializable]
        private class KeyContainer
        {
            public string publicKey;
            public string privateKey;
        }

        #endregion
    }
}

using UnityEngine;
namespace DogGuns_Games.vamsir
{
    public class VamserMobBase : MonoBehaviour, IObjectPoolSpawnerSettable
    {
        public ObjectPoolSpawner objectPoolSpawner { get; set; }


        public float Mob_Speed { get; set; }
        protected float Mob_Hp { get; set; }
        public float Mob_AttackDamage { get; set; }
        public float Mob_AttackSpeed { get; set; }
        public float Mob_AttackRange { get; set; }
        public float Mob_StunTime { get; set; }
        protected bool  Mob_IsDie { get; set; }
        protected bool  Mob_IsHit { get; set; }

        protected PlayerBase player; // 플레이어 참조를 저장할 필드

        public bool ismove;
        public enum MobState
        {
            Idle,
            Move,
            Stun,
            Attack,
            Die
        }

        [SerializeField] private MobState mobState;

        public virtual void OnEnable()
        {
            // objectPoolSpawner는 풀에서 생성될 때 외부에서 할당해 주므로 Find는 불필요합니다.
            Mob_IsDie = false;
            PlayStateManager.OnGamePause += Pause;
            PlayStateManager.OnGameResume += Resume;
            PlayStateManager.OnGameOver += OnGameOver;
        }

        private void OnDisable()
        {
            PlayStateManager.OnGamePause -= Pause;
            PlayStateManager.OnGameResume -= Resume;
            PlayStateManager.OnGameOver -= OnGameOver;
        }

        private void OnGameOver()
        {
            ismove = false;
        }

        private void OnValidate()
        {
            if (Application.isPlaying)
            {
                // 플레이 모드에서만 SetMobState 호출
                SetMobState(mobState);
            }
        }
        /// <summary>
        /// 외부에서 플레이어(타겟)를 설정합니다.
        /// </summary>
        public virtual void SetTarget(PlayerBase target)
        {
            player = target;
        }
        private void Pause()
        {
            ismove = false;
        }

        private void Resume()
        {
            ismove = true;
        }

        public void SetMobState(MobState state)
        {
            switch (state)
            {
                case MobState.Idle: Mob_Idle(); 
                    break;
                case MobState.Move: Mob_Move(); 
                    break;
                case MobState.Stun: Mob_Stun(); 
                    break;
                case MobState.Attack: Mob_Attack(); 
                    break;
                case MobState.Die: Mob_Die();
                    break;
            }
        }

        protected virtual void Mob_Idle()
        {
        }

        protected virtual void Mob_Move()
        {

        }

        protected virtual void Mob_Stun()
        {

        }

        protected virtual void Mob_hit()
        {

        }

        protected virtual void Mob_Attack()
        {
        }

        protected virtual void Mob_Die()
        {
            if (!Mob_IsDie)
            {
                Mob_IsDie = true;
                objectPoolSpawner.MobObjectPool.Release(this);
                PlayerDataManagerDontdesytoy.Instance.scritpableobjPlayerData.nowPlayMObkillCOunt++;
                Debug.Log("Die : " + name);
            }
        }
    }
}

