using System;
using Cysharp.Threading.Tasks;
using DG.Tweening;
using UnityEngine;

namespace DogGuns_Games.vamsir
{
    public class Normal_Mob : VamserMobBase
    {
        [Header("<color=green>플레이어 무기")] 
        private Weaphon_base player_Weaphon;

        //피격 물체가 발사체인지 구분
        private bool _isHitByShoot;

        [Header("몹 스탯")]
        [SerializeField] private float initialHp = 100f;
        [SerializeField] private float initialSpeed = 1f;
        [SerializeField] private float initialAttackDamage = 10f;
        [SerializeField] private float initialAttackSpeed = 1f;
        [SerializeField] private float initialAttackRange = 1f;
        [SerializeField] private float initialStunTime = 0.1f;

        private void Awake()
        {
            DOTween.SetTweensCapacity(500, 50);
        }

        private void Start()
        {
            // Init() 호출을 SetTarget으로 이동하여 player 참조가 보장되도록 합니다.
        }

        private void Init()
        {
            if (player != null)
            {
                player_Weaphon = player.WeaphonBase;
                if (player_Weaphon != null)
                {
                    _isHitByShoot = player_Weaphon.isShooting;
                }
            }

            Mob_Hp = initialHp;
            Mob_Speed = initialSpeed;
            Mob_AttackDamage = initialAttackDamage;
            Mob_AttackSpeed = initialAttackSpeed;
            Mob_AttackRange = initialAttackRange;
            Mob_StunTime = initialStunTime;

            Mob_IsDie = false;
            Mob_IsHit = false;
        }

        public override void SetTarget(PlayerBase target)
        {
            base.SetTarget(target);
            Init();
        }

        public override void OnEnable()
        {
            base.OnEnable();
            // Init() 호출을 SetTarget으로 이동하여 player 참조가 보장되도록 합니다.
            SetMobState(MobState.Move);
        }


        private void FixedUpdate()
        {
            if (!ismove || player == null) // player가 null이면 이동 로직을 실행하지 않습니다.
            {
                if (ismove) transform.DOKill();
                return;
            }

            // 플레이어를 추적하는 로직
            Vector3 direction = (player.transform.position - transform.position).normalized;
            transform.position += direction * Mob_Speed * Time.fixedDeltaTime;

            // 플레이어 방향으로 몹 회전 (좌우 반전)
            if (direction.x != 0)
            {
                // direction.x > 0 이면 오른쪽을 보도록 180도 회전 (스프라이트가 왼쪽을 보고 있을 경우)
                // direction.x < 0 이면 왼쪽을 보도록 0도 회전
                float yRotation = direction.x > 0 ? 180f : 0f;
                transform.rotation = Quaternion.Euler(0, yRotation, 0);
            }
        }

        private void OnCollisionEnter2D(Collision2D other)
        {
            if (_isHitByShoot)
            {
                HandleCollision(other);
            }
        }

        private void OnCollisionStay2D(Collision2D other)
        {
            if (!_isHitByShoot)
            {
                HandleCollision(other);
            }
        }

        private void HandleCollision(Collision2D other)
        {
            if (!Mob_IsHit && other.gameObject.CompareTag("Player_Attack"))
            {
                HitCooltime(other).Forget();
                Debug.Log("_isHitByShoot: "+_isHitByShoot);
            }
        }

        private async UniTask HitCooltime(Collision2D other)
        {
            Mob_IsHit = true;

            float attackPower = player_Weaphon.attackPower;
            float stunTime = player_Weaphon.mobStunTime;

            await UniTask.Yield();
            Mob_Hp -= attackPower;

            if (Mob_Hp <= 0)
            {
                SetMobState(MobState.Die);
            }
            else
            {
                Mob_StunTime = stunTime;
                SetMobState(MobState.Stun);
            }

            Mob_IsHit = false;
        }

        protected override void Mob_Idle()
        {
        //    Debug.Log("Idle");
        }

        protected override void Mob_Move()
        {
            ismove = true;
        }

        protected override void Mob_Stun()
        {
         //   Debug.Log("Stun");

            ismove = false;

            DOVirtual.DelayedCall(Mob_StunTime, () => { SetMobState(MobState.Move); });
        }

        protected override void Mob_hit()
        {
            base.Mob_hit();
        }

        protected override void Mob_Attack()
        {
        //    Debug.Log("Attack");
        }

        protected override void Mob_Die()
        {
            base.Mob_Die();
            transform.DOKill();
        //    Debug.Log("Die");
        }
    }
}

using System;
using Cysharp.Threading.Tasks;
using DG.Tweening;
using UnityEngine;

namespace DogGuns_Games.vamsir
{
    public class Normal_Mob : VamserMobBase
    {
        [Header("<color=green>플레이어 무기")] 
        private Weaphon_base player_Weaphon;

        //피격 물체가 발사체인지 구분
        private bool _isHitByShoot;

        [Header("몹 스탯")]
        [SerializeField] private float initialHp = 100f;
        [SerializeField] private float initialSpeed = 1f;
        [SerializeField] private float initialAttackDamage = 10f;
        [SerializeField] private float initialAttackSpeed = 1f;
        [SerializeField] private float initialAttackRange = 1f;
        [SerializeField] private float initialStunTime = 0.1f;

        private void Awake()
        {
            DOTween.SetTweensCapacity(500, 50);
        }

        private void Start()
        {
            // Init() 호출을 SetTarget으로 이동하여 player 참조가 보장되도록 합니다.
        }

        private void Init()
        {
            if (player != null)
            {
                player_Weaphon = player.WeaphonBase;
                if (player_Weaphon != null)
                {
                    _isHitByShoot = player_Weaphon.isShooting;
                }
            }

            Mob_Hp = initialHp;
            Mob_Speed = initialSpeed;
            Mob_AttackDamage = initialAttackDamage;
            Mob_AttackSpeed = initialAttackSpeed;
            Mob_AttackRange = initialAttackRange;
            Mob_StunTime = initialStunTime;

            Mob_IsDie = false;
            Mob_IsHit = false;
        }

        public override void SetTarget(PlayerBase target)
        {
            base.SetTarget(target);
            Init();
        }

        public override void OnEnable()
        {
            base.OnEnable();
            // Init() 호출을 SetTarget으로 이동하여 player 참조가 보장되도록 합니다.
            SetMobState(MobState.Move);
        }


        private void FixedUpdate()
        {
            if (!ismove || player == null) // player가 null이면 이동 로직을 실행하지 않습니다.
            {
                if (ismove) transform.DOKill();
                return;
            }

            // 플레이어를 추적하는 로직
            Vector3 direction = (player.transform.position - transform.position).normalized;
            transform.position += direction * Mob_Speed * Time.fixedDeltaTime;

            // 플레이어 방향으로 몹 회전 (좌우 반전)
            if (direction.x != 0)
            {
                // direction.x > 0 이면 오른쪽을 보도록 180도 회전 (스프라이트가 왼쪽을 보고 있을 경우)
                // direction.x < 0 이면 왼쪽을 보도록 0도 회전
                float yRotation = direction.x > 0 ? 180f : 0f;
                transform.rotation = Quaternion.Euler(0, yRotation, 0);
            }
        }

        private void OnCollisionEnter2D(Collision2D other)
        {
            if (_isHitByShoot)
            {
                HandleCollision(other);
            }
        }

        private void OnCollisionStay2D(Collision2D other)
        {
            if (!_isHitByShoot)
            {
                HandleCollision(other);
            }
        }

        private void HandleCollision(Collision2D other)
        {
            if (!Mob_IsHit && other.gameObject.CompareTag("Player_Attack"))
            {
                HitCooltime(other).Forget();
                LogManager.Log("_isHitByShoot: "+_isHitByShoot);
            }
        }

        private async UniTask HitCooltime(Collision2D other)
        {
            Mob_IsHit = true;

            float attackPower = player_Weaphon.attackPower;
            float stunTime = player_Weaphon.mobStunTime;

            await UniTask.Yield();
            Mob_Hp -= attackPower;

            if (Mob_Hp <= 0)
            {
                SetMobState(MobState.Die);
            }
            else
            {
                Mob_StunTime = stunTime;
                SetMobState(MobState.Stun);
            }

            Mob_IsHit = false;
        }

        protected override void Mob_Idle()
        {
            LogManager.Log("Idle");
        }

        protected override void Mob_Move()
        {
            ismove = true;
        }

        protected override void Mob_Stun()
        {
            LogManager.Log("Stun");
            ismove = false;
            DOVirtual.DelayedCall(Mob_StunTime, () => { SetMobState(MobState.Move); });
        }

        protected override void Mob_hit()
        {
            base.Mob_hit();
        }

        protected override void Mob_Attack()
        {
            LogManager.Log("Attack");
        }

        protected override void Mob_Die()
        {
            base.Mob_Die();
            transform.DOKill();
            LogManager.Log("Die");
        }
    }
}

using System.Collections;
using System.Collections.Generic;
using Cysharp.Threading.Tasks;
using UnityEngine;
using UnityEngine.AddressableAssets;
using UnityEngine.Pool;
using Random = UnityEngine.Random;

namespace DogGuns_Games.vamsir
{
    /// <summary>
    /// 뱀서라이크 게임의 오브젝트 풀 관리 및 스폰 시스템
    /// </summary>
    public class ObjectPoolSpawner : MonoBehaviour
    {
        #region 필드 및 속성
        private PlayerBase _player;
        // 오브젝트 풀 참조
        public IObjectPool<VamserMobBase> MobObjectPool { get; private set; }
        public IObjectPool<EXP_Obj> ExpObjectPool { get; private set; }
        public IObjectPool<Coin_Obj> CoinObjectPool { get; private set; }

        [Header("<color=green>몹 오브젝트</color>")]
        [SerializeField] private int poolSizeMobCount = 20;

        [Header("<color=green>몹 프리팹</color>")]
        [SerializeField] private AssetReferenceGameObject mobPrefabReference;

        [Header("<color=green>몹 오브젝트 스폰 위치</color>")]
        [SerializeField] private Transform mobParent;

        // 몹 카운트 관련
        private int _mobCount;
        public int MobCount => _mobCount;

        private int _mobSpawnWave;
        public int MobSpawnWave => _mobSpawnWave;

        [Header("<color=green>경험치 오브젝트</color>")]
        [SerializeField] private AssetReferenceGameObject expPrefabReference;
        [SerializeField] private AssetReferenceGameObject bigExpPrefabReference;

        [Header("<color=green>코인 오브젝트</color>")]
        [SerializeField] private AssetReferenceGameObject coinPrefabReference;
        [SerializeField] private float coinSpawnPercent = 25;

        // 로드된 프리팹 캐시
        private readonly Dictionary<AssetReferenceGameObject, GameObject> _loadedPrefabs = new Dictionary<AssetReferenceGameObject, GameObject>();

        // 스폰 제어 변수
        private bool _isSpawningAllowed = true;

        // 기타 참조
        private Camera _mainCamera;

        #endregion

        #region 초기화 및 라이프사이클

        /// <summary>
        /// 컴포넌트 초기화
        /// </summary>
         private void Awake()
         {
             _mainCamera = Camera.main;
         }

        /// <summary>
        /// 오브젝트 풀 초기화
        /// </summary>
        private void InitializePools()
        {
            // 몹 오브젝트 풀 초기화
            MobObjectPool = new ObjectPool<VamserMobBase>(
                Create_Mob,
                OnGet_Mob,
                OnRelease_Mob,
                OnDestroy_PoolObject,
                maxSize: poolSizeMobCount
            );

            // 경험치 오브젝트 풀 초기화
            ExpObjectPool = new ObjectPool<EXP_Obj>(
                Create_EXP,
                OnGet_PoolObject,
                OnRelease_PoolObject,
                OnDestroy_PoolObject,
                maxSize: poolSizeMobCount
            );

            // 코인 오브젝트 풀 초기화
            CoinObjectPool = new LinkedPool<Coin_Obj>(
                Create_Coin,
                OnGet_PoolObject,
                OnRelease_PoolObject,
                OnDestroy_PoolObject,
                maxSize: poolSizeMobCount
            );
        }

        /// <summary>
        /// 이벤트 구독 설정
        /// </summary>
        private void OnEnable()
        {
            SubscribeToEvents();
        }

        /// <summary>
        /// 게임 상태 이벤트 구독
        /// </summary>
        private void SubscribeToEvents()
        {
            PlayStateManager.OnGamePause -= Pause;
            PlayStateManager.OnGameResume -= Resume;
            PlayStateManager.OnGameOver -= GameEnd;

            PlayStateManager.OnGamePause += Pause;
            PlayStateManager.OnGameResume += Resume;
            PlayStateManager.OnGameOver += GameEnd;
        }

        /// <summary>
        /// 이벤트 구독 해제
        /// </summary>
        private void OnDisable()
        {
            UnsubscribeFromEvents();
        }

        /// <summary>
        /// VamserLikeGameManager에 의해 호출되어 스포너를 초기화하고 몹 스폰을 시작합니다.
        /// </summary>
        /// <param name="player">스폰된 플레이어의 참조</param>
        public async UniTask InitializeAndStartSpawning(PlayerBase player)
        {
            _player = player;
            if (_player == null)
            {
                Debug.LogError("플레이어 참조가 null입니다. 몹 스폰을 시작할 수 없습니다.");
                return;
            }

            // Addressable에서 모든 프리팹 비동기 로드
            await LoadAllPrefabsAsync();

            if (!ArePrefabsLoaded())
            {
                Debug.LogError("필수 프리팹 로드에 실패했습니다. 스폰을 시작할 수 없습니다.");
                return;
            }

            // 프리팹 로드 후 풀 초기화
            InitializePools();

            Debug.Log("ObjectPoolSpawner가 플레이어 참조를 받고 스폰을 시작합니다.");

            // GameStart 로직
            if (PlayStateManager.instance.isPlay)
            {
                // 초기 몹 스폰
                SpawnInitialMobs();
                _mobSpawnWave = 1;
            }
        }
        /// <summary>
        /// 게임 상태 이벤트 구독 해제
        /// </summary>
        private void UnsubscribeFromEvents()
        {
            PlayStateManager.OnGamePause -= Pause;
            PlayStateManager.OnGameResume -= Resume;
            PlayStateManager.OnGameOver -= GameEnd;
        }

        #endregion

        #region 게임 상태 관리

        /// <summary>
        /// 게임 일시정지 처리
        /// </summary>
        private void Pause()
        {
            _isSpawningAllowed = false;
            Debug.Log("오브젝트 스폰 일시 중지됨");
        }

        /// <summary>
        /// 게임 재개 처리
        /// </summary>
        private void Resume()
        {
            _isSpawningAllowed = true;
            Debug.Log("오브젝트 스폰 재개됨");
        }

        /// <summary>
        /// 게임 종료 시 모든 오브젝트 풀 정리
        /// </summary>
        private void GameEnd()
        {
            _isSpawningAllowed = false;

            // 모든 오브젝트 풀 정리
            MobObjectPool?.Clear();
            ExpObjectPool?.Clear();
            CoinObjectPool?.Clear();

            Debug.Log("게임 종료: 모든 오브젝트 풀 정리됨");
        }

        #endregion

        #region 몹 스폰 및 관리

        /// <summary>
        /// 초기 몹 스폰
        /// </summary>
        private void SpawnInitialMobs()
        {
            for (int i = 0; i < poolSizeMobCount; i++)
            {
                if (_isSpawningAllowed)
                {
                    MobObjectPool.Get();
                    _mobCount++;
                }
            }
        }

        /// <summary>
        /// 남은 몹이 있는지 체크하고 없으면 리스폰 예약
        /// </summary>
        private void CheckMob()
        {
            if (_mobCount <= 0)
            {   
                // 몹이 모두 죽었을때 3초후 리스폰
                Invoke(nameof(ReSpawn), 3);
            }
        }

        /// <summary>
        /// 다음 웨이브 몹 리스폰
        /// </summary>
        private void ReSpawn()
        {
            if (!_isSpawningAllowed) return;

            _mobSpawnWave++;
            poolSizeMobCount += 5;

            Debug.Log($"Wave: {_mobSpawnWave}, 몹 스폰 수: {poolSizeMobCount}");

            for (int i = 0; i < poolSizeMobCount; i++)
            {
                if (_isSpawningAllowed)
                {
                    MobObjectPool.Get();
                    _mobCount++;
                }
            }
        }

        /// <summary>
        /// 지정된 몹 위치에 경험치 오브젝트 스폰
        /// </summary>
        private void SpawnExp(VamserMobBase obj)
        {
            if (!_isSpawningAllowed) return;

            EXP_Obj exp = ExpObjectPool.Get();
            exp.transform.position = obj.transform.position;
        }

        /// <summary>
        /// 확률에 따라 지정된 몹 위치에 코인 오브젝트 스폰
        /// </summary>
        private void SpawnCoin(VamserMobBase obj)
        {
            if (!_isSpawningAllowed) return;

            if (SpawnRandom(coinSpawnPercent))
            {
                Coin_Obj coin = CoinObjectPool.Get();
                coin.transform.position = obj.transform.position;
            }
        }

        #endregion

        #region 오브젝트 풀 - 몹

        /// <summary>
        /// 몹 오브젝트 생성
        /// </summary>
        private VamserMobBase Create_Mob()
        {
            return CreatePoolObject<VamserMobBase>(mobPrefabReference);
        }

        /// <summary>
        /// 몹 오브젝트 풀에서 가져올 때 처리
        /// </summary>
        private void OnGet_Mob(VamserMobBase mob)
        {
            OnGet_PoolObject(mob);
            MoveObjectOffScreen(mob);
            mob.SetTarget(_player);
        }

        /// <summary>
        /// 몹 오브젝트를 풀에 반환할 때 처리
        /// </summary>
        private void OnRelease_Mob(VamserMobBase obj)
        {
            OnRelease_PoolObject(obj);
            _mobCount--;

            // 남은 몹 수 체크
            CheckMob();

            // 몹이 죽었을 때 아이템 생성
            SpawnExp(obj);
            SpawnCoin(obj);
        }

        #endregion

        #region 오브젝트 풀 - 경험치

        /// <summary>
        /// 경험치 오브젝트 생성
        /// </summary>
        private EXP_Obj Create_EXP()
        {
            // TODO: 큰 경험치는 일정 웨이브 이후 또는 특정 조건에서 생성
            bool canSpawnBigExp = _mobSpawnWave >= 5 && Random.value > 0.9f;
            AssetReferenceGameObject prefabRef = canSpawnBigExp ? bigExpPrefabReference : expPrefabReference;
            return CreatePoolObject<EXP_Obj>(prefabRef);
        }

        #endregion

        #region 오브젝트 풀 - 코인

        /// <summary>
        /// 코인 오브젝트 생성
        /// </summary>
        private Coin_Obj Create_Coin()
        {
            return CreatePoolObject<Coin_Obj>(coinPrefabReference);
        }

        #endregion

        #region 공통 풀링 로직

        /// <summary>
        /// 제네릭 오브젝트 생성 메서드
        /// </summary>
        private T CreatePoolObject<T>(AssetReferenceGameObject prefabRef) where T : MonoBehaviour
        {
            if (!_loadedPrefabs.TryGetValue(prefabRef, out var prefab) || prefab == null)
            {
                Debug.LogError($"{typeof(T).Name}의 프리팹이 로드되지 않았습니다.");
                return null;
            }

            T obj = Instantiate(prefab, mobParent).GetComponent<T>();

            // 오브젝트 타입에 따라 추가 설정
            if (obj is IObjectPoolSpawnerSettable poolObj)
            {
                poolObj.objectPoolSpawner = this;
            }

            return obj;
        }

        /// <summary>
        /// 오브젝트 활성화 공통 처리
        /// </summary>
        private void OnGet_PoolObject<T>(T obj) where T : MonoBehaviour
        {
            obj.gameObject.SetActive(true);
        }

        /// <summary>
        /// 오브젝트 비활성화 공통 처리
        /// </summary>
        private void OnRelease_PoolObject<T>(T obj) where T : MonoBehaviour
        {
            obj.gameObject.SetActive(false);
        }

        /// <summary>
        /// 오브젝트 파괴 공통 처리
        /// </summary>
        private void OnDestroy_PoolObject<T>(T obj) where T : MonoBehaviour
        {
            if (obj != null)
            {
                Destroy(obj.gameObject);
            }
        }

        #endregion

        #region 공통 유틸리티

        /// <summary>
        /// 모든 프리팹을 비동기적으로 로드합니다.
        /// </summary>
        private async UniTask LoadAllPrefabsAsync()
        {
            var tasks = new List<UniTask>
            {
                LoadPrefabAsync(mobPrefabReference),
                LoadPrefabAsync(expPrefabReference),
                LoadPrefabAsync(bigExpPrefabReference),
                LoadPrefabAsync(coinPrefabReference)
            };
            await UniTask.WhenAll(tasks);
        }

        /// <summary>
        /// 단일 프리팹을 로드하고 캐시에 저장합니다.
        /// </summary>
        private async UniTask LoadPrefabAsync(AssetReferenceGameObject reference)
        {
            if (reference == null || !reference.RuntimeKeyIsValid()) return;
            if (_loadedPrefabs.ContainsKey(reference)) return;

            var handle = Addressables.LoadAssetAsync<GameObject>(reference);
            await handle.ToUniTask();
            if (handle.Status == UnityEngine.ResourceManagement.AsyncOperations.AsyncOperationStatus.Succeeded)
            {
                _loadedPrefabs[reference] = handle.Result;
            }
            else
            {
                Debug.LogError($"에셋 로드 실패: {reference.AssetGUID}");
            }
        }

        /// <summary>
        /// 필수 프리팹이 모두 로드되었는지 확인합니다.
        /// </summary>
        private bool ArePrefabsLoaded()
        {
            return _loadedPrefabs.ContainsKey(mobPrefabReference) &&
                   _loadedPrefabs.ContainsKey(expPrefabReference) &&
                   _loadedPrefabs.ContainsKey(coinPrefabReference);
        }

        /// <summary>
        /// 오브젝트를 화면 밖에 위치시키는 메서드
        /// </summary>
        private void MoveObjectOffScreen(VamserMobBase obj)
        {
            if (_mainCamera == null)
            {
                Debug.LogWarning("Main Camera가 설정되지 않았습니다.");
                return;
            }

            // 뷰포트 밖의 랜덤 위치 생성
            float x = Random.Range(-2.0f, 2.0f);
            float y = Random.Range(-2.0f, 2.0f);

            // 위치가 뷰포트 내부인 경우 강제로 외부로 이동
            if (x > 0 && x < 1) x = x < 0.5f ? -0.1f : 1.1f;
            if (y > 0 && y < 1) y = y < 0.5f ? -0.1f : 1.1f;

            // 뷰포트 위치를 월드 위치로 변환
            Vector3 offScreenPosition = _mainCamera.ViewportToWorldPoint(
                new Vector3(x, y, _mainCamera.nearClipPlane)
            );

            // 객체 위치 설정 및 활성화
            obj.transform.position = offScreenPosition;
            obj.gameObject.SetActive(true);
        }

        /// <summary>
        /// 확률에 따른 스폰 여부 결정
        /// </summary>
        private bool SpawnRandom(float percent)
        {
            return Random.Range(0, 100) < percent;
        }


        #endregion
    }

    /// <summary>
    /// ObjectPoolSpawner 참조를 설정하기 위한 인터페이스
    /// </summary>
    public interface IObjectPoolSpawnerSettable
    {
        ObjectPoolSpawner objectPoolSpawner { set; }
    }
}

using System.Collections;
using System.Collections.Generic;
using Cysharp.Threading.Tasks;
using UnityEngine;
using UnityEngine.AddressableAssets;
using UnityEngine.Pool;
using Random = UnityEngine.Random;

namespace DogGuns_Games.vamsir
{
    /// <summary>
    /// 뱀서라이크 게임의 오브젝트 풀 관리 및 스폰 시스템
    /// </summary>
    public class ObjectPoolSpawner : MonoBehaviour
    {
        #region 필드 및 속성
        private PlayerBase _player;
        // 오브젝트 풀 참조
        public IObjectPool<VamserMobBase> MobObjectPool { get; private set; }
        public IObjectPool<EXP_Obj> ExpObjectPool { get; private set; }
        public IObjectPool<Coin_Obj> CoinObjectPool { get; private set; }

        [Header("<color=green>몹 오브젝트</color>")]
        [SerializeField] private int poolSizeMobCount = 20;

        [Header("<color=green>몹 프리팹</color>")]
        [SerializeField] private AssetReferenceGameObject mobPrefabReference;

        [Header("<color=green>몹 오브젝트 스폰 위치</color>")]
        [SerializeField] private Transform mobParent;

        // 몹 카운트 관련
        private int _mobCount;
        public int MobCount => _mobCount;

        private int _mobSpawnWave;
        public int MobSpawnWave => _mobSpawnWave;

        [Header("<color=green>경험치 오브젝트</color>")]
        [SerializeField] private AssetReferenceGameObject expPrefabReference;
        [SerializeField] private AssetReferenceGameObject bigExpPrefabReference;

        [Header("<color=green>코인 오브젝트</color>")]
        [SerializeField] private AssetReferenceGameObject coinPrefabReference;
        [SerializeField] private float coinSpawnPercent = 25;

        // 로드된 프리팹 캐시
        private readonly Dictionary<AssetReferenceGameObject, GameObject> _loadedPrefabs = new Dictionary<AssetReferenceGameObject, GameObject>();

        // 스폰 제어 변수
        private bool _isSpawningAllowed = true;

        // 기타 참조
        private Camera _mainCamera;

        #endregion

        #region 초기화 및 라이프사이클

        /// <summary>
        /// 컴포넌트 초기화
        /// </summary>
         private void Awake()
         {
             _mainCamera = Camera.main;
         }

        /// <summary>
        /// 오브젝트 풀 초기화
        /// </summary>
        private void InitializePools()
        {
            // 몹 오브젝트 풀 초기화
            MobObjectPool = new ObjectPool<VamserMobBase>(
                Create_Mob,
                OnGet_Mob,
                OnRelease_Mob,
                OnDestroy_PoolObject,
                maxSize: poolSizeMobCount
            );

            // 경험치 오브젝트 풀 초기화
            ExpObjectPool = new ObjectPool<EXP_Obj>(
                Create_EXP,
                OnGet_PoolObject,
                OnRelease_PoolObject,
                OnDestroy_PoolObject,
                maxSize: poolSizeMobCount
            );

            // 코인 오브젝트 풀 초기화
            CoinObjectPool = new LinkedPool<Coin_Obj>(
                Create_Coin,
                OnGet_PoolObject,
                OnRelease_PoolObject,
                OnDestroy_PoolObject,
                maxSize: poolSizeMobCount
            );
        }

        /// <summary>
        /// 이벤트 구독 설정
        /// </summary>
        private void OnEnable()
        {
            SubscribeToEvents();
        }

        /// <summary>
        /// 게임 상태 이벤트 구독
        /// </summary>
        private void SubscribeToEvents()
        {
            PlayStateManager.OnGamePause -= Pause;
            PlayStateManager.OnGameResume -= Resume;
            PlayStateManager.OnGameOver -= GameEnd;

            PlayStateManager.OnGamePause += Pause;
            PlayStateManager.OnGameResume += Resume;
            PlayStateManager.OnGameOver += GameEnd;
        }

        /// <summary>
        /// 이벤트 구독 해제
        /// </summary>
        private void OnDisable()
        {
            UnsubscribeFromEvents();
        }

        /// <summary>
        /// VamserLikeGameManager에 의해 호출되어 스포너를 초기화하고 몹 스폰을 시작합니다.
        /// </summary>
        /// <param name="player">스폰된 플레이어의 참조</param>
        public async UniTask InitializeAndStartSpawning(PlayerBase player)
        {
            _player = player;
            if (_player == null)
            {
                LogManager.LogError("플레이어 참조가 null입니다. 몹 스폰을 시작할 수 없습니다.");
                return;
            }

            // Addressable에서 모든 프리팹 비동기 로드
            await LoadAllPrefabsAsync();

            if (!ArePrefabsLoaded())
            {
                LogManager.LogError("필수 프리팹 로드에 실패했습니다. 스폰을 시작할 수 없습니다.");
                return;
            }

            // 프리팹 로드 후 풀 초기화
            InitializePools();

            LogManager.Log("ObjectPoolSpawner가 플레이어 참조를 받고 스폰을 시작합니다.");

            // GameStart 로직
            if (PlayStateManager.instance.isPlay)
            {
                // 초기 몹 스폰
                SpawnInitialMobs();
                _mobSpawnWave = 1;
            }
        }
        /// <summary>
        /// 게임 상태 이벤트 구독 해제
        /// </summary>
        private void UnsubscribeFromEvents()
        {
            PlayStateManager.OnGamePause -= Pause;
            PlayStateManager.OnGameResume -= Resume;
            PlayStateManager.OnGameOver -= GameEnd;
        }

        #endregion

        #region 게임 상태 관리

        /// <summary>
        /// 게임 일시정지 처리
        /// </summary>
        private void Pause()
        {
            _isSpawningAllowed = false;
            LogManager.Log("오브젝트 스폰 일시 중지됨");
        }

        /// <summary>
        /// 게임 재개 처리
        /// </summary>
        private void Resume()
        {
            _isSpawningAllowed = true;
            LogManager.Log("오브젝트 스폰 재개됨");
        }

        /// <summary>
        /// 게임 종료 시 모든 오브젝트 풀 정리
        /// </summary>
        private void GameEnd()
        {
            _isSpawningAllowed = false;

            // 모든 오브젝트 풀 정리
            MobObjectPool?.Clear();
            ExpObjectPool?.Clear();
            CoinObjectPool?.Clear();

            LogManager.Log("게임 종료: 모든 오브젝트 풀 정리됨");
        }

        #endregion

        #region 몹 스폰 및 관리

        /// <summary>
        /// 초기 몹 스폰
        /// </summary>
        private void SpawnInitialMobs()
        {
            for (int i = 0; i < poolSizeMobCount; i++)
            {
                if (_isSpawningAllowed)
                {
                    MobObjectPool.Get();
                    _mobCount++;
                }
            }
        }

        /// <summary>
        /// 남은 몹이 있는지 체크하고 없으면 리스폰 예약
        /// </summary>
        private void CheckMob()
        {
            if (_mobCount <= 0)
            {   
                // 몹이 모두 죽었을때 3초후 리스폰
                Invoke(nameof(ReSpawn), 3);
            }
        }

        /// <summary>
        /// 다음 웨이브 몹 리스폰
        /// </summary>
        private void ReSpawn()
        {
            if (!_isSpawningAllowed) return;

            _mobSpawnWave++;
            poolSizeMobCount += 5;

            LogManager.Log($"Wave: {_mobSpawnWave}, 몹 스폰 수: {poolSizeMobCount}");

            for (int i = 0; i < poolSizeMobCount; i++)
            {
                if (_isSpawningAllowed)
                {
                    MobObjectPool.Get();
                    _mobCount++;
                }
            }
        }

        /// <summary>
        /// 지정된 몹 위치에 경험치 오브젝트 스폰
        /// </summary>
        private void SpawnExp(VamserMobBase obj)
        {
            if (!_isSpawningAllowed) return;

            EXP_Obj exp = ExpObjectPool.Get();
            exp.transform.position = obj.transform.position;
        }

        /// <summary>
        /// 확률에 따라 지정된 몹 위치에 코인 오브젝트 스폰
        /// </summary>
        private void SpawnCoin(VamserMobBase obj)
        {
            if (!_isSpawningAllowed) return;

            if (SpawnRandom(coinSpawnPercent))
            {
                Coin_Obj coin = CoinObjectPool.Get();
                coin.transform.position = obj.transform.position;
            }
        }

        #endregion

        #region 오브젝트 풀 - 몹

        /// <summary>
        /// 몹 오브젝트 생성
        /// </summary>
        private VamserMobBase Create_Mob()
        {
            return CreatePoolObject<VamserMobBase>(mobPrefabReference);
        }

        /// <summary>
        /// 몹 오브젝트 풀에서 가져올 때 처리
        /// </summary>
        private void OnGet_Mob(VamserMobBase mob)
        {
            OnGet_PoolObject(mob);
            MoveObjectOffScreen(mob);
            mob.SetTarget(_player);
        }

        /// <summary>
        /// 몹 오브젝트를 풀에 반환할 때 처리
        /// </summary>
        private void OnRelease_Mob(VamserMobBase obj)
        {
            OnRelease_PoolObject(obj);
            _mobCount--;

            // 남은 몹 수 체크
            CheckMob();

            // 몹이 죽었을 때 아이템 생성
            SpawnExp(obj);
            SpawnCoin(obj);
        }

        #endregion

        #region 오브젝트 풀 - 경험치

        /// <summary>
        /// 경험치 오브젝트 생성
        /// </summary>
        private EXP_Obj Create_EXP()
        {
            // TODO: 큰 경험치는 일정 웨이브 이후 또는 특정 조건에서 생성
            bool canSpawnBigExp = _mobSpawnWave >= 5 && Random.value > 0.9f;
            AssetReferenceGameObject prefabRef = canSpawnBigExp ? bigExpPrefabReference : expPrefabReference;
            return CreatePoolObject<EXP_Obj>(prefabRef);
        }

        #endregion

        #region 오브젝트 풀 - 코인

        /// <summary>
        /// 코인 오브젝트 생성
        /// </summary>
        private Coin_Obj Create_Coin()
        {
            return CreatePoolObject<Coin_Obj>(coinPrefabReference);
        }

        #endregion

        #region 공통 풀링 로직

        /// <summary>
        /// 제네릭 오브젝트 생성 메서드
        /// </summary>
        private T CreatePoolObject<T>(AssetReferenceGameObject prefabRef) where T : MonoBehaviour
        {
            if (!_loadedPrefabs.TryGetValue(prefabRef, out var prefab) || prefab == null)
            {
                LogManager.LogError($"{typeof(T).Name}의 프리팹이 로드되지 않았습니다.");
                return null;
            }

            T obj = Instantiate(prefab, mobParent).GetComponent<T>();

            // 오브젝트 타입에 따라 추가 설정
            if (obj is IObjectPoolSpawnerSettable poolObj)
            {
                poolObj.objectPoolSpawner = this;
            }

            return obj;
        }

        /// <summary>
        /// 오브젝트 활성화 공통 처리
        /// </summary>
        private void OnGet_PoolObject<T>(T obj) where T : MonoBehaviour
        {
            obj.gameObject.SetActive(true);
        }

        /// <summary>
        /// 오브젝트 비활성화 공통 처리
        /// </summary>
        private void OnRelease_PoolObject<T>(T obj) where T : MonoBehaviour
        {
            obj.gameObject.SetActive(false);
        }

        /// <summary>
        /// 오브젝트 파괴 공통 처리
        /// </summary>
        private void OnDestroy_PoolObject<T>(T obj) where T : MonoBehaviour
        {
            if (obj != null)
            {
                Destroy(obj.gameObject);
            }
        }

        #endregion

        #region 공통 유틸리티

        /// <summary>
        /// 모든 프리팹을 비동기적으로 로드합니다.
        /// </summary>
        private async UniTask LoadAllPrefabsAsync()
        {
            var tasks = new List<UniTask>
            {
                LoadPrefabAsync(mobPrefabReference),
                LoadPrefabAsync(expPrefabReference),
                LoadPrefabAsync(bigExpPrefabReference),
                LoadPrefabAsync(coinPrefabReference)
            };
            await UniTask.WhenAll(tasks);
        }

        /// <summary>
        /// 단일 프리팹을 로드하고 캐시에 저장합니다.
        /// </summary>
        private async UniTask LoadPrefabAsync(AssetReferenceGameObject reference)
        {
            if (reference == null || !reference.RuntimeKeyIsValid()) return;
            if (_loadedPrefabs.ContainsKey(reference)) return;

            var handle = Addressables.LoadAssetAsync<GameObject>(reference);
            await handle.ToUniTask();
            if (handle.Status == UnityEngine.ResourceManagement.AsyncOperations.AsyncOperationStatus.Succeeded)
            {
                _loadedPrefabs[reference] = handle.Result;
            }
            else
            {
                LogManager.LogError($"에셋 로드 실패: {reference.AssetGUID}");
            }
        }

        /// <summary>
        /// 필수 프리팹이 모두 로드되었는지 확인합니다.
        /// </summary>
        private bool ArePrefabsLoaded()
        {
            return _loadedPrefabs.ContainsKey(mobPrefabReference) &&
                   _loadedPrefabs.ContainsKey(expPrefabReference) &&
                   _loadedPrefabs.ContainsKey(coinPrefabReference);
        }

        /// <summary>
        /// 오브젝트를 화면 밖에 위치시키는 메서드
        /// </summary>
        private void MoveObjectOffScreen(VamserMobBase obj)
        {
            if (_mainCamera == null)
            {
                LogManager.LogWarning("Main Camera가 설정되지 않았습니다.");
                return;
            }

            // 뷰포트 밖의 랜덤 위치 생성
            float x = Random.Range(-2.0f, 2.0f);
            float y = Random.Range(-2.0f, 2.0f);

            // 위치가 뷰포트 내부인 경우 강제로 외부로 이동
            if (x > 0 && x < 1) x = x < 0.5f ? -0.1f : 1.1f;
            if (y > 0 && y < 1) y = y < 0.5f ? -0.1f : 1.1f;

            // 뷰포트 위치를 월드 위치로 변환
            Vector3 offScreenPosition = _mainCamera.ViewportToWorldPoint(
                new Vector3(x, y, _mainCamera.nearClipPlane)
            );

            // 객체 위치 설정 및 활성화
            obj.transform.position = offScreenPosition;
            obj.gameObject.SetActive(true);
        }

        /// <summary>
        /// 확률에 따른 스폰 여부 결정
        /// </summary>
        private bool SpawnRandom(float percent)
        {
            return Random.Range(0, 100) < percent;
        }


        #endregion
    }

    /// <summary>
    /// ObjectPoolSpawner 참조를 설정하기 위한 인터페이스
    /// </summary>
    public interface IObjectPoolSpawnerSettable
    {
        ObjectPoolSpawner objectPoolSpawner { set; }
    }
}

using System;
using UnityEngine;

namespace DogGuns_Games.vamsir
{
    public class PlayStateManager : MonoBehaviour
    {
        public static Action OnGameStart;
        public static Action OnGamePause;
        public static Action OnGameResume;
        public static Action OnGameOver;

        public static PlayStateManager instance;

        public bool isPlay = false;

        private void Awake()
        {
            if (instance == null)
            {
                instance = this;
            }
        }

        public enum GameState
        {
            Play,
            Pause,
            Resume,
            GameOver
        }

        private GameState _playState;

        public GameState PlayState
        {
            get => _playState;
            set
            {
                _playState = value;
                SetMobState(_playState);
            }
        }

        private void OnValidate()
        {
            if (Application.isPlaying)
            {
                // 플레이 모드에서만 SetMobState 호출
                SetMobState(PlayState);
            }
        }

        private void Start()
        {
           Invoke(nameof(Gamestart), 1f);
        }

        private void Gamestart()
        {
            PlayState = GameState.Play;
        }

        public void SetMobState(GameState state)
        {
            switch (state)
            {
                case GameState.Play:
                    OnGameStart?.Invoke();
                    Debug.Log( "OnGameStart");
                    break;
                case GameState.Pause:
                    OnGamePause?.Invoke();
                    Debug.Log( "OnGamePause");
                    break;
                case GameState.Resume:
                    OnGameResume?.Invoke();
                    Debug.Log( "OnGameResume");
                    break;
                case GameState.GameOver:
                    OnGameOver?.Invoke();
                    Debug.Log( "OnGameOver");
                    break;
            }
        }
    }
}

