            // AudioManager.Instance.PlaySound("PlayerHit");
            LogManager.Log("피격 효과 재생");
        }

        /// <summary>
        /// 플레이어 대기 동작
        /// </summary>
        public virtual void Player_Idle()
        {
            // 자식 클래스에서 구현
        }

        /// <summary>
        /// 플레이어 이동 동작
        /// </summary>
        public virtual void PlayerMovement()
        {
            // 자식 클래스에서 구현
        }

        #endregion

        #region 경험치 시스템

        /// <summary>
        /// 경험치를 추가하고 레벨업을 체크합니다.
        /// </summary>
        /// <param name="expAmount">추가할 경험치 양</param>
        public void AddExperience(float expAmount)
        {
            CurrentExp += expAmount;

            // 경험치 변경 이벤트 발생
            OnExpChanged?.Invoke(CurrentExp, MaxExp);

            // 레벨업 체크
            CheckLevelUp();
        }

        /// <summary>
        /// 레벨업 조건을 체크하고 레벨업을 처리합니다.
        /// </summary>
        private void CheckLevelUp()
        {
            while (CurrentExp >= MaxExp)
            {
                // 경험치 차감
                CurrentExp -= MaxExp;
                // 레벨 증가
                Level++;
                // 다음 레벨 필요 경험치 계산
                MaxExp = CalculateMaxExpForLevel(Level);
                // 레벨업 이벤트 발생
                OnLevelUp?.Invoke(Level);
                // 레벨업 효과 처리
                HandleLevelUp();
                LogManager.Log($"레벨업! 현재 레벨: {Level}, 필요 경험치: {MaxExp}");
                // 경험치 변경 이벤트를 레벨업마다 호출하여 UI가 즉시 반영되도록 함
                OnExpChanged?.Invoke(CurrentExp, MaxExp);
            }
            // 경험치 변경 이벤트 재발생 (레벨업 후 UI 업데이트용)
            OnExpChanged?.Invoke(CurrentExp, MaxExp);
        }

        /// <summary>
        /// 레벨에 따른 최대 경험치를 계산합니다.
        /// </summary>
        /// <param name="level">현재 레벨</param>
        /// <returns>해당 레벨에서 필요한 최대 경험치</returns>
        private float CalculateMaxExpForLevel(float level)
        {
            // 레벨 0→1: 10, 레벨 1→2: 20, ...
            return (level + 1) * 10f;
        }

        /// <summary>
        /// 레벨업 시 플레이어 능력치 증가를 처리합니다.
        /// </summary>
        private void HandleLevelUp()
        {
            // 레벨업 시 스탯 증가
            AttackPower += 5f;
            Health += 20f;
            Defense += 2f;
            MoveSpeed += 0.1f;

            // 레벨업 사운드 효과 (선택사항)
            // SoundManager.PlaySound(Sound.SFX, "LevelUp");
        }

        /// <summary>
        /// 현재 경험치 진행률을 0~1 범위로 반환합니다.
        /// </summary>
        /// <returns>경험치 진행률 (0~1)</returns>
        public float GetExpProgress()
        {
            return MaxExp > 0 ? CurrentExp / MaxExp : 0f;
        }

        #endregion

        #region 유틸리티 메서드

        /// <summary>
        /// 지정된 시간 후에 액션을 실행합니다.
        /// </summary>
        /// <param name="delay">지연 시간(초)</param>
        /// <param name="action">실행할 액션</param>
        /// <param name="cancellationToken">취소 토큰(선택 사항)</param>
        /// <returns>UniTask</returns>
        public UniTask DelayAction(float delay, Action action, CancellationToken cancellationToken = default)
        {
            return UniTask.Delay(
                TimeSpan.FromSeconds(delay), 
                cancellationToken: cancellationToken
            ).ContinueWith(() => {
                if (!cancellationToken.IsCancellationRequested)
                {
                    action?.Invoke();
                }
            });
        }

        #endregion
    }
}

using Cysharp.Threading.Tasks;
using UnityEngine;
using DG.Tweening;
using UnityEngine.UI;

namespace DogGuns_Games.vamsir
{
    public class VamPlayerControll : MonoBehaviour
    {

        //todo: 플레이어의 HP가 O 이하로 떨어지면 게임 오버 처리

        #region 필드 및 변수

        [Header("<color=green>Player Object")] [SerializeField]
        private GameObject player;

        [Header("<color=green>Player charactor Object")] [SerializeField]
        private PlayerBase playerCharactor;

        [Header("<color=green>Player HP_IU")] [SerializeField]
        private Slider playerHpSliderPrefab;

        private float _playerHpSliderValue = 0;

        private Animator _playerAnimator;

        [Header("<color=green>Joystick")] [SerializeField]
        private VariableJoystick variableJoystick;

        [Header("<color=green>camera")] [SerializeField]
        private Camera cameraTransform;

        [Header("<color=green>Move Duration")] [SerializeField]
        private float moveDuration = 0.1f;


        private Slider _playerHpSlider; // 인스턴스화된 슬라이더 참조 추가

        [Header("<color=green>Map Range")] [SerializeField]
        private SpriteRenderer mapRange;


        bool _isGameStart = false;

        bool _isAttack = false;

        #endregion

        #region Unity 라이프사이클

        private void Start()
        {
            PlayStateManager.OnGameStart += PlayerInit;
            PlayStateManager.OnGamePause += Pause;
            PlayStateManager.OnGameResume += Resume;
        }

        private void OnDestroy()
        {
            PlayStateManager.OnGameStart -= PlayerInit;
            PlayStateManager.OnGamePause -= Pause;
            PlayStateManager.OnGameResume -= Resume;
        }

        private void FixedUpdate()
        {
            if (_isGameStart)
            {
                PlayerMovement();
                FallowCamera();
                UpdatePlayerHpSlider();
            }
        }

        #endregion

        #region 게임 상태 관리

        private void PlayerInit()
        {
            // 캐릭터 스폰과의 레이스 컨디션을 피하기 위해 초기화 로직을 AssignCharacter로 이동했습니다.
            // OnGameStart 이벤트에서는 게임 시작 플래그만 설정합니다.
            _isGameStart = true;
        }

        /// <summary>
        /// VamserLikeGameManager가 플레이어 스폰 후 호출하여 캐릭터를 설정합니다.
        /// </summary>
        /// <param name="character">스폰된 플레이어 캐릭터</param>
        public void AssignCharacter(PlayerBase character)
        {
            if (playerCharactor == null && character != null)
            {
                playerCharactor = character;
                playerCharactor.transform.SetParent(player.gameObject.transform);
                _playerAnimator = playerCharactor.GetComponent<Animator>();
                cameraTransform = Camera.main;
                Set_playerHpSlider();
            }
        }

        private void Pause()
        {
            _isGameStart = false;
        }

        private void Resume()
        {
            _isGameStart = true;
        }

        #endregion

        #region UI 설정

        private void Set_playerHpSlider()
        {
            _playerHpSlider = Instantiate(playerHpSliderPrefab, player.transform);
            _playerHpSlider.transform.localPosition = new Vector3(0, -0.4f, 0);
            _playerHpSlider.maxValue = playerCharactor.Health;
            _playerHpSlider.value = playerCharactor.Health;
            _playerHpSliderValue = playerCharactor.Health;
        }

        private void UpdatePlayerHpSlider()
        {
            if (playerCharactor == null)
            {
                PlayerInit();
                return;
            }

            // 현재 체력 값이 이전 값과 다를 때만 슬라이더 업데이트
            if (_playerHpSlider != null && Mathf.Abs(_playerHpSliderValue - playerCharactor.Health) > 0.001f)
            {
                _playerHpSliderValue = playerCharactor.Health;
                _playerHpSlider.value = _playerHpSliderValue;

                // 플레이어 HP가 0 이하로 떨어지면 게임 오버 처리
                if (playerCharactor.Health <= 0)
                {
                    TriggerGameOver();
                }
                {
                    TriggerGameOver();

        /// <summary>
        /// 게임 오버를 트리거합니다.
        /// </summary>
        private void TriggerGameOver()
        {
            // 게임을 멈추고 게임 오버 상태로 설정
            _isGameStart = false;

            // PlayStateManager를 통해 게임 오버 이벤트 발생
            if (PlayStateManager.instance != null)
            {
                PlayStateManager.instance.PlayState = PlayStateManager.GameState.GameOver;
            }

            Debug.Log("Player HP reached 0 - Game Over!");
        }
                }
                {
                    TriggerGameOver();

